(window.GIM_TS=window.GIM_TS||{})["Nedarim.4"]={"from":96,"a":[["\u0003דלי ציפתא\u0004 \u0005[הרים\u0006 את \u0005המחצלת]\u0006 שהיה יושב עליה \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003לשלוחא\u0004 \u0005[לשליח]:\u0006 \u0003חזי מאי איכא\u0004 \u0005[ראה מה\u0006 ש\u0005יש\u0006 כאן\u0005]\u0006 שנעשה לו נס ונתמלא המקום דינרים, להראות לו שאם היה רוצה בכך היה לו ממון רב. והסביר: \u0003מיהו\u0004 \u0005[בכל זאת],\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דאיתהני בהדין עלמא\u0004 \u0005[שאהנה בעולם הזה].\u0006","אגב המסופר כאן על עוניים של חכמים וכיצד בא להם עושר בדרך מופלאה, מספרים כי \u0003ר' עקיבא איתקדשת ליה ברתיה (דבר) דכלבא שבוע\u0004 \u0005[התקדשה לו בתו של (בר) כלבא שבוע].\u0006 \u0003שמע\u0004 זאת \u0003(בר) כלבא שבוע, אדרה\u0004 \u0005[הדיר אותה]\u0006 \u0003הנאה מכל נכסיה\u0004 \u0005[נכסיו].\u0006 \u0003אזלא ואיתנסיבה ליה\u0004 \u0005[הלכה ונישאה לו]\u0006 לר' עקיבא.","\u0003בסיתוא הוה גנו בי תיבנא\u0004 \u0005[בחורף היו ישנים ב\u0006מחסן \u0005תבן],\u0006 \u0003הוה קא מנקיט ליה תיבנא מן מזייה\u0004 \u0005[היה מוציא לו\u0006 את \u0005התבן משערותיו].\u0006 \u0003אמר לה: אי הואי\u0004 \u0005[אם היה]\u0006 \u0003לי\u0004 כסף, \u0003רמינא ליך\u0004 \u0005[הייתי נותן לך]\u0006 בראשך עטרה של \u0003ירושלים דדהבא\u0004 \u0005[של זהב].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא \u0003אידמי להון כאנשא\u0004 \u0005[נדמה להם כאדם]\u0006 \u0003וקא קרי אבבא\u0004 \u0005[וקרא,\u0006 דפק \u0005על הדלת].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הבו לי פורתא דתיבנא\u0004 \u0005[תנו לי מעט תבן]\u0006 \u0003דילדת אתתי, ולית\u0004 \u0005[שילדה אשתי, ואין]\u0006 \u0003לי מידעם לאגונה\u0004 \u0005[דבר להשכיבה\u0006 עליו\u0005].\u0006 \u0003אמר לה ר' עקיבא לאנתתיה\u0004 \u0005[לאשתו]:\u0006 \u0003חזי גברא\u0004 \u0005[ראי איש]\u0006 ש\u0003אפילו תיבנא לא אית ליה\u0004 \u0005[תבן אין לו]\u0006 ואנו יכולים לשמוח בחלקנו, שלפחות יש לנו תבן לשכב עליו.","\u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל הוי בי רב\u0004 \u0005[לך היה בבית הרב]\u0006 ולמד תורה. \u0003אזל תרתי סרי שנין\u0004 \u0005[הלך\u0006 ועסק בתורה \u0005שתים עשרה שנים]\u0006 \u0003קמי\u0004 \u0005[לפני]\u0006 \u0003ר' אליעזר ור' יהושע. למישלם תרתי סרי שנין קא אתא לביתיה\u0004 \u0005[בסוף שתים עשרה שנה בא לביתו],\u0006 \u0003שמע מן אחורי ביתיה\u0004 \u0005[מאחורי ביתו]\u0006 \u0003דקאמר לה חד רשע לדביתהו\u0004 \u0005[שאומר לה רשע אחד לאשתו]:\u0006 \u0003שפיר עביד ליך אבוך\u0004 \u0005[יפה,\u0006 כראוי \u0005עשה לך אביך]\u0006 שהדירך מנכסיו; \u0003חדא דלא דמי ליך\u0004 \u0005[\u0006דבר \u0005אחד] —\u0006 \u0005[ש\u0006בעלך \u0005אינו דומה,\u0006 אינו ראוי, \u0005לך].\u0006 \u0003ועוד, [שבקך\u0004\u0005]\u0006 \u0003ארמלות חיות כולהון שנין\u0004 \u0005[הניח אותך כאלמנה בחייו כל השנים\u0006 הללו\u0005].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי צאית לדילי\u0004 \u0005[אם\u0006 הוא \u0005שומע לי]\u0006 — \u0003ליהוי תרתי סרי שנין אחרנייתא\u0004 \u0005[יהיה\u0006 שם עוד \u0005שתים עשרה שנים אחרות].\u0006 \u0003אמר\u0004 ר' עקיבא: \u0003הואיל ויהבת\u0004 \u0005[ונתנה]\u0006 \u0003לי רשותא\u0004 \u0005[רשות]\u0006 בדבריה אלה, \u0003איהדר\u0004 \u0005[אחזור]\u0006 \u0003לאחורי. הדר אזל הוה תרתי סרי שני אחרנייתא\u0004 \u0005[חזר\u0006 ו\u0005הלך\u0006 ו\u0005היה\u0006 בבית המדרש \u0005שתים עשרה שנים אחרות].\u0006","\u0003אתא בעשרין וארבעה אלפין זוגי תלמידי\u0004 \u0005[בא ועשרים וארבעה אלפי זוגות תלמידים\u0006 עימו\u0005].\u0006 \u0003נפוק כולי עלמא לאפיה\u0004 \u0005[יצאו הכל ל\u0006קבל \u0005פניו]\u0006 משום שהיה אדם גדול ומפורסם בישראל, \u0003ואף היא קמת למיפק לאפיה\u0004 \u0005[עמדה לצאת ל\u0006קבל \u0005פניו].\u0006 \u0003אמר לה ההוא רשיעא\u0004 \u0005[אותו רשע]:\u0006 \u0003ואת להיכא\u0004 \u0005[להיכן]\u0006 את הולכת? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"יודע צדיק נפש בהמתו\"\u0004 (משלי יב, י) ולא יבזה אותה. \u0003אתת לאיתחזויי ליה\u0004 \u0005[באה להיראות לפניו,\u0006 לפני ר' עקיבא\u0005],\u0006 \u0003קא מדחן לה רבנן\u0004 \u0005[\u0006ו\u0005היו חכמים דוחים אותה]\u0006 שלא ידעו מי היא. \u0003אמר להון\u0004 \u0005[להם]\u0006 ר' עקיבא רבם: \u0003הניחו לה,\u0004 כי כל התורה \u0003שלי ושלכם —\u0004 \u0003שלה הוא. שמע (בר) כלבא שבוע\u0004 שזה ר' עקיבא חתנו, \u0003אתא ואיתשיל על נידריה ואשתריי\u0004 \u0005[בא\u0006 לפני החכמים \u0005ונשאל על נדרו ו\u0006ביקש ל\u0005התירו],\u0006 \u0003ואשתרי\u0004 \u0005[והותר].\u0006","ומספרים: \u0003מן שית מילי איעתר\u0004 \u0005[משישה דברים התעשר]\u0006 \u0003ר' עקיבא: מן\u0004 הכסף שנתן לו \u0003כלבא שבוע\u0004 לאחר שהותר הנדר, \u0003מן אילא דספינתא\u0004 \u0005[מאיל הספינה].\u0006 \u0003דכל ספינתא עבדין ליה מין עינא\u0004 \u0005[שכל ספינה עושים לה\u0006 בחרטומה צורה של \u0005מין צאן]\u0006 וממלאים אותו בכסף. \u0003זימנא חדא אנשיוה על כיף ימא\u0004 \u0005[פעם אחת שכחו\u0006 הספנים איל זה \u0005על חוף הים]\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003הוא,\u0004 ר' עקיבא, \u0003אשכחיה\u0004 \u0005[\u0006ו\u0005מצא אותו],\u0006 ובתוכו היה מוטמן הרבה כסף.","\u0003ו\u0004כן הרוויח ממון גדול \u0003מן גווזא\u0004 \u0005[מבול עץ]\u0006 כיצד? \u0003דזימנא חדא יהיב\u0004 \u0005[שפעם אחת נתן]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003לספונאי\u0004 \u0005[למלחים]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אייתי לי מדעם\u0004 \u0005[הביאו לי משהו]\u0006 \u0003ולא אשכחו\u0004 \u0005[מצאו]\u0006 \u0003אלא גווזא על כיף ימא\u0004 \u0005[בול עץ על חוף הים].\u0006 \u0003אתיוה ליה\u0004 \u0005[הביאו אותו לו].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003עביד מרנא עליה\u0004 \u0005[ימתין אדוננו עליו]\u0006 עד שנביא דבר טוב מזה, \u0003אישתכח דהוה מלי דינרי\u0004 \u0005[נמצא שהיה,\u0006 אותו בול עץ, \u0005מלא דינרים],\u0006 כיצד? \u0003דזימנא חדא טבעת ספינתא\u0004 \u0005[שפעם אחת טבעה ספינה]\u0006 \u0003וכולי עיסקא\u0004 \u0005[וכל העסק,\u0006 כל הכסף\u0005]\u0006 שהיה לאנשי הספינה \u0003הוה מחית בההוא גווזא ואישתכח בההוא זימנא\u0004 \u0005[היה מונח באותו בול עץ ונמצא באותה פעם].\u0006","וכן נתעשר ר' עקיבא \u0003דמן דסרוקיתא\u0004 \u0005[מ\u0006שיירה של \u0005ישמעאלים],\u0006 \u0003ומן מטרוניתא\u0004 \u0005[גבירה]\u0006 אחת שלווה ר' עקיבא ממנה כסף, ואמר שהקדוש ברוך הוא והים הסמוך לביתה יהיו ערבים לפרעון. משהגיע זמן הפרעון חלה ר' עקיבא ולא יכול היה לבוא לפרוע חובה. יצאה אותה גבירה ועמדה על שפת הים ואמרה : רבונו של עולם, ידוע לפניך כי לך ולים האמנתי ורק בשלכם הלויתיו אותם מעות. ונזדמן שבת המלך נשתגעה והשליכה לים ארנק מלא תכשיטים, וסחפו הים עד לפתח ביתה ומצאה הגבירה תכשיטים אלה. משהחלים ר' עקיבא בא לפניה והתנצל על כך שלא יכול היה לפרוע חובו בזמן. ואמרה שכבר קיבלה את התשלום מן הערב, ונשאר כסף ההלוואה בידי ר' עקיבא."],["\u0003ומן אשתו של טורנוסרופוס\u0004 שהתגיירה ונתנה לו את ממונה, \u0003ומן קטיעא בר שלום\u0004 שהיה שר רומאי שהוריש לו את כל רכושו.","בדומה לזה מסופר: \u0003רב גמדא יהיב\u0004 \u0005[נתן]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003לספונאי לאתויי בהון מידעם\u0004 \u0005[למלחים להביא בהם דבר]\u0006 עבורו ממדינת הים, \u0003לא אשכחו\u0004 \u0005[מצאו]\u0006 דבר חשוב, \u0003אתיוה ליה בהון קופא\u0004 \u0005[הביאו לו בהם קוף\u0006 אחד\u0005].\u0006 \u0003אישתמיט על לחרתא\u0004 \u0005[ברח\u0006 הקוף \u0005ונכנס לחור\u0006 אחד\u0005],\u0006 \u0003חפרו בתריה\u0004 \u0005[אחריו]\u0006 לתפוס אותו, \u0003אשכחוה דרביע על מרגלייתא, אייתינון ליה כולהון\u0004 \u0005[מצאו אותו ש\u0006הוא \u0005רובץ על מרגליות\u0006 ו\u0005הביאו לו\u0006 לרב גמדא \u0005את כולן].\u0006 אגב כך מספרים עוד מעשים שאירעו בחכמים.","\u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003בת קיסר לר' יהושע בן חנניה:\u0004 יש בך אמנם \u0003תורה מפוארה,\u0004 אולם היא נתונה \u0003בכלי מכוער,\u0004 שלא היה אדם יפה. \u0003אמר לה: למדי מבית אבוך\u0004 \u0005[אביך],\u0006 \u0003במה מניחין\u0004 אתם \u0003יין? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003במאני דפחרא\u0004 \u0005[בכלי חרס].\u0006 \u0003אמר לה: כולי עלמא בפחרא ואתון במאני דפחרא\u0004 \u0005[כל העולם\u0006 מניחים \u0005בחרס ו\u0006גם \u0005אתם בכלי חרס],\u0006 אם כן מה ההבדל בין הקיסר לאחרים?! \u0003אתון אחיתון במאני דכספא ודהבא\u0004 \u0005[אתם הניחו\u0006 את היין \u0005בכלי כסף וזהב]!\u0006","\u0003אזלת ורמת חמרא במאני דכספא ודהבא, וסרי\u0004 \u0005[הלכה ושמה\u0006 את \u0005היין בכלי כסף וזהב, והסריח].\u0006 \u0003אמר לה\u0004 ר' יהושע: \u0003אף אורייתא\u0004 \u0005[התורה]\u0006 \u0003כן,\u0004 אם היא מונחת בכלי יפה, באדם יפה, היא מתקלקלת. שאלה אותו: \u0003והאיכא שפירין וגמירין\u0004 \u0005[והרי יש\u0006 אנשים \u0005יפים ו\u0006בכל זאת \u0005למודי\u0006 תורה\u0005]!\u0006 \u0003אמר לה: אי הוו סנו, הוו גמירין טפי\u0004 \u0005[אם היו מכוערים, היו למודים יותר].\u0006","ועוד מסופר על \u0003ההיא דאתיא לקמיה\u0004 \u0005[אשה אחת שבאה לפני]\u0006 \u0003רב יהודה מ\u0004העיר \u0003נהרדעא לדינא\u0004 \u0005[לדין]\u0006 \u0003ואיתחייבת מן דינא\u0004 \u0005[והתחייבה בדין].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003שמואל רבך הכי דנן\u0004 \u0005[כך היה\u0006 גם \u0005דן\u0006 אותי\u0005]?!\u0006 \u0003אמר לה: ידעת ליה\u0004 \u0005[\u0006וכי \u0005הכרת אותו]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003גוצא ורבה כריסיה אוכם ורבה שיניה\u0004 \u0005[נמוך\u0006 היה, \u0005וכרסו גדולה, שחור\u0006 היה, \u0005ושיניו גדולות].\u0006 \u0003אמר לה: לבזוייה קאתית\u0004 \u0005[לבזות אותו באת]\u0006 שכך את מתארת אותו? \u0003תיהוי ההיא אתתא בשמתא\u0004 \u0005[תהיה אשה זו בחרם].\u0006 וכיון שהחרימה \u0003פקעה ומתה.\u0004","שנינו במשנה שהנודר מתבשיל \u0003מותר בביצה טורמיטא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה היא]\u0006 \u0003ביצה טורמיטא? אמר שמואל: עבדא דעביד לה\u0004 \u0005[עבד ש\u0006יודע \u0005לעשות אותה]\u0006 \u0003שוי אלפא דינרי\u0004 \u0005[שווה אלף דינרים].\u0006 \u0003ו\u0004כך היא נעשית; \u0003מעייל לה\u0004 \u0005[ומכניס אותה]\u0006 \u0003אלפא זימני במיא חמימי ואלפא זימני במיא קרירי\u0004 \u0005[אלף פעמים במים חמים ואלף פעמים במים קרים]\u0006 \u0003עד דמתזוטרא כי היכי דבלעיתה\u0004 \u0005[שנעשית קטנה כדי ש\u0006אפשר \u0005לבלוע אותה\u0006 שלימה\u0005],\u0006 \u0003ואם אית כיבא\u0004 \u0005[ואם יש\u0006 איזה \u0005פצע]\u0006 במעיים — \u0003סריך עלה\u0004 \u0005[נדבק בה]\u0006 בביצה משהו מן הפצע, \u0003וכד נפקא ואתיא\u0004 \u0005[וכאשר\u0006 היא \u0005יוצאת ובאה]\u0006 \u0003ידע אסיא מאי סמא מתבעי ליה ובמאי מתסי\u0004 \u0005[יודע הרופא איזה סם נצרך לו,\u0006 לחולה, \u0005ובמה\u0006 הוא \u0005מתרפא]\u0006 ולכן היא חשובה מאד לרפואה.","מסופר: \u0003שמואל הוה בדיק נפשיה בקולחא\u0004 \u0005[היה בודק\u0006 את \u0005עצמו בקלח]\u0006 שהיה בולע לצורך זה, והיה הדבר גורם לו להתעלף \u0003עד דמסתרין אינשי ביתיה עליה שעריהון\u0004 \u0005[שהיו בני ביתו סותרים עליו את שערותיהם]\u0006 מחמת צער, שחשבו שהוא עומד למות. בדומה לנדרים יש עוד תחומי הלכה בהם מבחינים בין זנים שונים של מין פירות אחד.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 פועל ש\u0003היה עושה\u0004 (עובד) \u0003בכלופסין\u0004 (מין תאנים) — \u0003לא יאכל בבנות שבע\u0004 שהן מין אחר של תאנים, לפי שמותר לפועל לאכול רק מאותם הפירות שהוא עובד בהם. וכן העובד \u0003בבנות שבע\u0004 — \u0003לא יאכל בכלופסין.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה הם]\u0006 \u0003כלופסין\u0004 אלה? ומשיבים: \u0003מינא דתאיני דעבדין מנהון לפדי\u0004 \u0005[מין תאנים שעושים מהן\u0006 מיני \u0005לפתן].\u0006","מסופר: \u0003ההוא גברא דיהב עבדא לחבריה לאגמוריה אלפא מיני לפדי\u0004 \u0005[אדם אחד שנתן עבד לחבירו שילמד אותו\u0006 לעשות \u0005אלף מיני לפתן]\u0006 מתאנים, \u0003אגמריה תמני מאה\u0004 \u0005[לימד אותו\u0006 רק \u0005שמונה מאות].\u0006 \u0003אזמניה לדינא לקמיה\u0004 \u0005[הזמין אותו,\u0006 את המורה, \u0005לדין לפני]\u0006 \u0003רבי. אמר רבי: אבותינו אמרו \"נשינו טובה\"\u0004 (ראה איכה ג, יז), כלומר, שכחנו את הטובה שהיתה לנו, ומכל מקום ידעו טובה מהי, \u0003אנו אפילו בעינינו לא ראינו,\u0004 שהתפעל מכך שאפשר לעשות כל כך הרבה מיני מאכלים מתאנים בלבד.","מסופר: \u0003רבי עבד ליה הלולא\u0004 \u0005[עשה לו משתה\u0006 חתונה\u0005]\u0006 \u0003לר' שמעון ברבי\u0004 בנו, \u0003כתב\u0004 מישהו \u0003על בית גננא\u0004 \u0005[החופה]:\u0006 \u0003עשרין וארבעה אלפין ריבואין דינרין נפקו על בית גננא דין\u0004 \u0005[עשרים וארבעה אלף ריבוא דינרים הוצאו על בית החופה הזה],\u0006 \u0003ולא אזמניה\u0004 \u0005[הזמין]\u0006 את \u0003בר קפרא\u0004 לאותו משתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא שנעלב על שלא הוזמן לחופה: \u0003אם לעוברי רצונו\u0004 של מקום \u0003כך,\u0004 כלומר, אם לך שאין אתה נוהג כראוי — כך, יש גדולה ועושר — \u0003לעושי רצונו על אחת כמה וכמה.\u0004 שמע זאת רבי, \u0003אזמניה\u0004 \u0005[הזמין אותו],\u0006 חזר בו בר קפרא ו\u0003אמר: אם לעושי רצונו בעולם הזה כך —\u0004 \u0003לעולם הבא על אחת כמה וכמה\u0004 יהיה לו שכר. ומסבירים קצת את מהות היחסים ביניהם.","\u0003יומא דמחייך ביה\u0004 \u0005[יום שהיה צוחק בו]\u0006 \u0003רבי, אתיא פורענותא לעלמא\u0004 \u0005[היתה באה פורענות לעולם],\u0006 שהיה מכפר בכאביו על חטאי ישראל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לבר קפרא: לא תבדיחן ויהיבנא לך ארבעין גריוי חיטי\u0004 \u0005[אל תצחיק אותי ואתן לך ארבעים סאה חיטין]\u0006 בשכר זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא: \u0003ליחזי מר\u0004 \u0005[שיראה אדוני]\u0006"],["\u0003כל גריוא דבעינא שקילנא\u0004 \u0005[סאה שארצה אקח].\u0006 \u0003שקל דיקולא רבה, חפייה כופרא וסחפיה על רישיה\u0004 \u0005[לקח סל נצרים גדול, כיסה, מרח\u0006 \u0005אותו בזפת והפך אותו על ראשו],\u0006 \u0003ואזל\u0004 \u0005[והלך]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לרבי: \u0003ליכיל לי מר ארבעין גריוי חיטי דרשינא בך\u0004 \u0005[שימדוד לי אדוני ארבעים סאים חיטים שאני נושה בך].\u0006 \u0003אחוך\u0004 \u0005[צחק]\u0006 \u0003רבי\u0004 על המראה הזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003לאו אזהרתך\u0004 \u0005[\u0006וכי \u0005לא הזהרתיך]\u0006 ש\u0003לא תבדחן\u0004 \u0005[תצחיק אותי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חיטי דרשינא קא נסיבנא\u0004 \u0005[חיטים שאני נושה\u0006 בך \u0005אני לוקח]\u0006 ממך.","\u0003אמר לה בר קפרא לברתיה\u0004 \u0005[לבתו]\u0006 של \u0003רבי: למחר שתינא חמרא בריקודא דאבוך ובקירקני דאמך\u0004 \u0005[אשתה יין בריקוד של אביך ובקרקור של אמך].\u0006 ומסופר: \u0003בן אלעשה חתניה\u0004 \u0005[חתנו]\u0006 של \u0003רבי הוה\u0004 \u0005[היה],\u0006 \u0003ועשיר גדול הוה\u0004 \u0005[היה].\u0006 \u0003אזמניה\u0004 \u0005[הזמין אותו]\u0006 \u0003לבי הילולא\u0004 \u0005[לחתונה]\u0006 של \u0003ר' שמעון ברבי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא לרבי\u0004 בתוך המשתה: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש לשון \u0003\"תועבה\"\u0004 (ויקרא יח, כב) האמורה במשכב זכר? \u0003כל\u0004 מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי דהכין\u0004 \u0005[שכך]\u0006 \u0003הוא\u0004 הפירוש של \u0003\"תועבה\", פרכה\u0004 \u0005[פרך,\u0006 שבר \u0005אותה]\u0006 \u0003בר קפרא\u0004 והוכיח שאינו כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003פרשיה את\u0004 \u0005[פרש אותה אתה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תיתי דביתכי תירמי לי נטלא\u0004 \u0005[תבוא אשתך\u0006 ו\u0005תמזוג לי גביע\u0006 יין\u0005].\u0006 \u0003אתת רמיא ליה\u0004 \u0005[באה\u0006 ו\u0005מזגה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא \u0003לרבי: קום רקוד לי, דאימר\u0004 \u0005[\u0006כדי \u0005שאומר]\u0006 \u0003לך\u0004 מה פירוש הדבר. ומשעשה כן רבי אמר בר קפרא: \u0003הכי אמר רחמנא\u0004 \u0005[כך אמרה תורה]:\u0006 \u0003\"תועבה\"\u0004 פירושו — \u0003תועה אתה בה\u0004 בביאה זו, שאתה בא על זכר במקום על אשה.","כשהגיע \u0003לכסא אחרינא\u0004 \u0005[\u0006לשתות \u0005כוס אחרת]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תבל\"\u0004 (ויקרא יח, כג) האמור במשכב בהמה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003כי עניינא קדמאה\u0004 \u0005[כמו הענין\u0006 במקרה \u0005הקודם]\u0006 פירושים שונים שאת כולם פרך בר קפרא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר קפרא: \u0003עיביד\u0004 \u0005[עשה]\u0006 \u0003לי\u0004 ריקוד כבראשונה כדי ש\u0003אומר לך. עבד\u0004 \u0005[עשה\u0006 כן\u0005]\u0006 רבי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"תבל הוא\"\u0004 (ויקרא יח, כג) משמעו: וכי \u0003תבלין\u0004 טעם מיוחד \u0003יש בה\u0004 בביאת בהמה? \u0003מי שניא הדא\u0004 \u0005[האם שונה זאת]\u0006 ה\u0003ביאה מן כולהון\u0004 \u0005[מכל]\u0006 ה\u0003ביאות\u0004 האחרות, ומה הנאה מיוחדת יש לעושה מעשה מגונה זה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"זימה\"\u0004 האמורה באותה פרשה על נושא אשה ובתה (ויקרא יח, יז)? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עיביד כי עניינא קדמאה\u0004 \u0005[עשה\u0006 לי \u0005כמו הענין הקודם].\u0006 \u0003עבד\u0004 \u0005[עשה\u0006 רבי כן\u0005]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 בר קפרא, \"זימה\" פירושה: \u0003זו מה היא,\u0004 שאינו יודע מי נקראת אשתו ומי נקראת בת אשתו או אם אשתו. \u0003לא יכיל\u0004 \u0005[יכול]\u0006 עוד \u0003בן אלעשה למיסבל\u0004 \u0005[לסבול]\u0006 ולראות כיצד רבי משפיל את עצמו, \u0003קם ונפק\u0004 \u0005[ויצא]\u0006 \u0003הוא ואינתתיה מתמן\u0004 \u0005[ואשתו משם].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003בן אלעשה,\u0004 היכן מצינו עוד שמוזכר כאדם עשיר? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא לחנם פיזר בן אלעשה את מעותיו\u0004 בתספורתו המיוחדת \u0003אלא\u0004 כדי \u0003להראות בהן\u0004 במעותיו \u0003תספורת של כהן גדול\u0004 כיצד היא.","\u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על הכהנים: \u0003\"כסום יכסמו את ראשיהם\"\u0004 (יחזקאל מד, כ). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 תספורת זו היא \u0003כעין לולינית.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לולינית\"? אמר רב יהודה: תספרתא יחידתא\u0004 \u0005[תספורת מיוחדת].\u0006 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 היא \u0005בדיוק]?\u0006 \u0003אמר רבא: ראשו של זה בצד עיקרו של זה,\u0004 סופה של כל קווצת שיער מגיע עד לשורשי קווצת השיער האחרת, ואין אחת מהן עולה על השניה. \u0003והיינו\u0004 \u0005[וזוהי]\u0006 \u0003תספורת של כהן גדול,\u0004 ובן אלעשה הוציא ממון רב כדי שיספרוהו כך, על מנת שיוכלו לראות כיצד היה מסתפר הכהן הגדול.","שנינו שהנודר מן התבשיל מותר \u0003בדלעת הרמוצה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דלעת הרמוצה\"? אמר שמואל: קרא\u0004 \u0005[דלעת]\u0006 ממין הגדל במקום \u0003קרקוזאי\u0004 שאינה מתבשלת כראוי. \u0003רב אשי אמר: דלעת הטמונה ברמץ\u0004 (אפר של גחלים), ולכן היא קרויה רמוצה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרב אשי:\u0004 שנינו, \u0003ר' נחמיה אומר: דלעת ארמית היא דלעת המצרית,\u0004 והיא \u0003כלאים עם\u0004 הדלעת \u0003היונית,\u0004 והיא \u0003כלאים עם הרמוצה.\u0004 משמע מכאן שדלעת הרמוצה היא מין דלעת, ולא תיאור של אופן עשייתה. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה היא]\u0006 ונדחו דברי רב אשי.","\u0003הנודר ממעשה קדרה\u0004 — \u0003אין אסור אלא ממעשה רתחתא\u0004 (תבשילים שעיקר עשייתם בקדירה). אבל אם \u0003אמר \"קונם היורד לקדרה שאני טועם\"\u0004 — במקרה זה \u0003אסור בכל הנעשה בקדרה,\u0004 ואפילו נגמר בישולו בדבר אחר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר מן היורד לקדרה —\u0004 \u0003אסור\u0004 גם \u0003ביורד לאלפס\u0004 להתבשל שם. ומדוע? \u0003שכבר ירד לקדרה קודם שיורד לאלפס,\u0004 שבאלפס היו חוזרים ומטגנים דבר שכבר נתבשל קודם בקדירה. אבל אם נדר \u0003מן היורד לאלפס —\u0004 \u0003מותר ביורד לקדרה,\u0004 שהרי אין תבשיל זה יורד עוד לקדירה לאחר מכן. אם נדר \u0003מן הנעשה בקדרה —\u0004 \u0003מותר בנעשה באלפס,\u0004 שהרי אמר שהוא נודר רק מדברים שעיקר עשייתם הוא בקדירה. וכן הנודר \u0003מן הנעשה באלפס —\u0004 \u0003מותר בנעשה בקדרה.\u0004","\u0003הנודר מן היורד לתנור\u0004 סתם — \u0003אין אסור אלא בפת,\u0004 שהיא נקראת בפי אנשים דבר היורד לתנור. \u0003ואם אמר \"כל מעשה תנור עלי\" —\u0004 \u0003אסור בכל הנעשים בתנור,\u0004 ואפילו אינם פת."],["הנודר \"קונם עלי \u0003מן הכבוש\" —\u0004 \u0003אין אסור אלא מן הכבוש של ירק\u0004 שהוא סתם \"כבוש\" שבלשון בני אדם. אבל אם אמר \u0003\"כבוש שאני טועם\" —\u0004 \u0003אסור בכל\u0004 מיני \u0003הכבושים.\u0004 וכן אם אומר \u0003\"מן השלוק\" —\u0004 \u0003אינו אסור אלא מן השלוק של בשר\u0004 שהוא \"שלוק\" בלשון בני אדם. ואם אמר בלשון \u0003\"שלוק שאני טועם\" —\u0004 \u0003אסור בכל השלוקים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 אם \u0003אמר \"דכביש\u0004 \u0005[שכבוש]\u0006 אסור עלי \u0003\"\u0004\u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003\"דשליק\"\u0004 \u0005[ששלוק]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003\"דצלי\"\u0004 \u0005[שצלוי]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003\"דמליח\"\u0004 \u0005[שמלוח]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 דינו? \u0003היכין משמע\u0004 \u0005[כיצד המשמעות]\u0006 האם הכוונה היא לסוג מסויים שמקובל לקרוא לו בשם זה, או לכל המינים שהם בגדר זה? לשאלה זו לא נמצאה תשובה, ועדיין \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה.","הנודר \"קונם עלי \u0003מן הצלי\" —\u0004 \u0003אין אסור אלא מן הצלי של בשר,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ואם אמר \u0003\"צלי שאני טועם\" —\u0004 \u0003אסור בכל הצלויים.\u0004 וכן האומר \u0003\"מן המליח\" —\u0004 \u0003אין אסור אלא מן המליח של דג\u0004 שהוא סתם \"מליח\" בלשון בני אדם. אבל אם אמר \u0003\"מליח שאני טועם\" —\u0004 \u0003אסור בכל המלוחים.\u0004","אם אמר \u0003\"דג דגים שאני טועם\" —\u0004 \u0003אסור בהן\u0004 בדגים, \u0003בין גדולים בין קטנים, בין מלוחים בין תפלים, בין חיים בין מבושלים, ומותר בטרית טרופה,\u0004 שהוא מין דג קטן שחותכים אותו לחתיכות קטנות, \u0003ובציר\u0004 היוצא מן הדגים. שאין אלה נכללים בלשון בני אדם במונח \"דג\". \u0003הנודר מן הצחנה\u0004 שהיא תערובת דגים שלמים וחתוכים — \u0003אסור\u0004 אף \u0003בטרית טרופה,\u0004 כיון שיש בהם גם חתיכות דגים, \u0003ומותר בציר\u0004 של דגים \u0003ובמורייס\u0004 שהוא הנוזל היוצא משומנם של דגים. \u0003הנודר מטרית טרופה —\u0004 \u0003אסור בציר ובמורייס.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 אמר \u0003\"דג שאני טועם\" —\u0004 \u0003אסור ב\u0004דגים \u0003גדולים, ומותר בקטנים.\u0004 אמר \u0003\"דגה שאני טועם\" —\u0004 \u0003אסור בקטנים ומותר בגדולים. \"דג דגה שאני טועם\" —\u0004 \u0003אסור בין בגדולים בין בקטנים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 אתה למד ש\u0003\"דג שאני טועם\" גדול הוא —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימן ה' דג גדול לבלע את יונה\"\u0004 (יונה ב, א). אבל יש לשאול: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויתפלל יונה אל ה' אלהיו ממעי הדגה\"\u0004 (יונה ב, ב)! משמע שדג גדול קרוי גם \"דגה\"!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה איננו קשה];\u0006 \u0003דלמא פלטיה\u0004 \u0005[שמא פלט אותו]\u0006 \u0003דג גדול,\u0004 וחזר \u0003ובלעיה\u0004 \u0005[ובלע אותו]\u0006 \u0003דג קטן.\u0004 ומקשים מכתוב אחר: \u0003אלא \"והדגה אשר ביאר מתה\"\u0004 (שמות ז, כא) וכי דגים \u0003קטנים מתו, גדולים לא מתו?! אלא\u0004 יש לומר כי \u0003\"דגה\" משמע\u0004 דגים \u0003גדולים ומשמע קטנים\u0004 בלשון מקרא, \u0003ו\u0004אולם \u0003בנדרים הלך אחר לשון בני אדם,\u0004 ובני אדם קוראים \"דגה\" לדגים קטנים דווקא.","שנינו במשנה: \u0003הנודר מן הצחנה\u0004 אסור בטרית טרופה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אם \u0003אמר \"הרי עלי ציחין\" מאי\u0004 \u0005[מה]\u0006 יהיה דינו? האם הוא לשון צחנה, או לשון אחרת? לשאלה זו לא נמצאה תשובה ועדיןן \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה.","\u0003הנודר מן החלב\u0004 — \u0003מותר בקום,\u0004 שהוא נוזל היוצא מן החלב בזמן שמגבנים אותו, \u0003ור' יוסי אוסר.\u0004 הנודר \u0003מן הקום —\u0004 \u0003מותר בחלב. אבא שאול אומר: הנודר מן הגבינה\u0004 — \u0003אסור בה, בין\u0004 שהיא \u0003מלוחה ו\u0004בין שהיא \u0003טפלה\u0004 (בלי מלח). \u0003הנודר מן הבשר\u0004"],["\u0003מותר ברוטב\u0004 (מרק) \u0003ובקיפה\u0004 (מקפה עבה של בשר), \u0003ור' יהודה אוסר.\u0004","\u0003אמר ר' יהודה: מעשה ואסר עלינו ר' טרפון\u0004 אפילו \u0003בביצים שנתבשלו עמו,\u0004 עם הבשר. \u0003אמרו לו: כן הדבר,\u0004 אבל \u0003אימתי —\u0004 \u0003בזמן שיאמר \"בשר זה עלי\", שהנודר מן הדבר ונתערב באחר, אם יש בו\u0004 באחר \u0003בנותן טעם\u0004 מן האיסור — \u0003אסור.\u0004 אבל אם נודר \"מן הבשר\" סתם — אין כוונתו אלא לבשר עצמו.","\u0003הנודר מן היין —\u0004 \u0003מותר בתבשיל שיש בו טעם יין.\u0004 ואם \u0003אמר \"קונם יין זה שאני טועם\" ונפל\u0004 היין \u0003לתבשיל, אם יש בו\u0004 בתבשיל לאחר נפילת היין \u0003בנותן טעם\u0004 יין — \u0003הרי זה אסור.\u0004"],["שיטת ר' יוסי במשנה היא שהנודר מן החלב אסור בקום. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: הנודר \u0003\"מן העדשים\" —\u0004 \u0003אסור באשישים\u0004 (מאכלים הנעשים מעדשים), ו\u0003ר' יוסי מתיר.\u0004 ומכאן שר' יוסי אינו סבור שכל דבר הבא ממה שנדר ממנו נאסר גם כן, ובניגוד לדבריו ביחס לקום של חלב!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה כמקומו וחכם זה כמקומו].\u0006 \u0003באתרא דרבנן קרו לחלבא חלבא ולקומא קומא\u0004 \u0005[במקומם של חכמים קוראים לחלב חלב, ולקום קום],\u0006 ואילו \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003ר' יוסי לקומא נמי קרו ליה \"קומא דחלבא\"\u0004 \u0005[לקום גם כן היו קוראים לו \"קום של חלב\"],\u0006 וכיון שקרוי על שם החלב, לכן הנודר מן החלב אסור גם בקום.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר מן החלב —\u0004 \u0003מותר בקום, מן הקום —\u0004 \u0003מותר בחלב.\u0004 הנודר \u0003מן החלב —\u0004 \u0003מותר בגבינה, מן הגבינה —\u0004 \u0003מותר בחלב.\u0004 הנודר \u0003מן הרוטב —\u0004 \u0003מותר בקיפה, מן הקיפה —\u0004 \u0003מותר ברוטב. אם אמר \"בשר זה עלי\" —\u0004 \u0003אסור בו וברוטבו ובקיפו.\u0004","\u0003הנודר מן היין —\u0004 \u0003מותר בתבשיל שיש בו טעם יין, אמר: \"קונם יין זה שאיני טועם\" ונפל\u0004 יין זה \u0003לתוך התבשיל, אם יש בו\u0004 בתבשיל \u0003טעם יין —\u0004 \u0003הרי זה אסור,\u0004 שכיון שאמר \"שאני טועם\" הרי טועם טעם יין גם כשהוא בתערובת.","\u0003הנודר מן הענבים —\u0004 \u0003מותר ביין.\u0004 הנודר \u0003מן הזיתים —\u0004 \u0003מותר בשמן. אמר \"קונם זיתים וענבים אלו שאיני טועם\" —\u0004 \u0003אסור\u0004 גם \u0003בהן ו\u0004גם \u0003ביוצא מהן.\u0004","על האמור במשנה: \"קונם זיתים וענבים אלו שאיני טועם\" — אסור בהם וביוצא מהם, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 האם אסרו לו את היוצא מהם משום שאמר \u0003\"אלו\" דוקא, או\u0004 משום שאמר \u0003\"שאיני טועם\" דוקא?\u0004","ושואלים: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003\"אלו\" דוקא,\u0004 אם כן \u0003\"שאיני טועם\" למה לי?\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אמר \"שאיני טועם\", אי\u0004 \u0005[אם]\u0006 ש\u0003אמר\u0004 קודם לכן \u0003\"אלו\" —\u0004 \u0003מיתסר\u0004 \u0005[נאסר]\u0006 ביוצא מהם, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא —\u0004 \u0003לא,\u0004 אינו נאסר. ואם כן, אין פתרון לשאלה זו מלשון המשנה.","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: אמר \u0003\"קונם פירות האלו עלי\",\u0004 או אמר \u0003\"קונם הן לפי\" —\u0004 \u0003אסור בחילופיהן ובגידוליהן,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 יוצא מכאן ש\u0003ביוצא מהן מותר!\u0004 ומכאן אפשר להוכיח שהאיסור ביוצא מהם הוא משום שאמר \"איני טועם\", שהרי כשאמר \"אלו\" לא נאסר ביוצא מהם!","ודוחים: \u0003הוא הדין\u0004 ש\u0003אפילו ביוצא מהן אסור. והא עדיפא ליה לאשמועינן\u0004 \u0005[ו\u0006דבר \u0005זה\u0006 היה \u0005עדיף לו להשמיע לנו]\u0006 ש\u0003חילופיהן כגידוליהן דמי\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 ואף אלה אסורים, למרות שאין בהם דבר מממשותו של האיסור הראשון.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת מהמשכה של אותה משנה: האומר \u0003\"שאיני אוכל\",\u0004 או שאמר \u0003\"שאיני טועם\" —\u0004 \u0003מותר בחילופיהן ובגידוליהן,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003היוצא מהן —\u0004 \u0003אסור,\u0004 ומכאן ש\"אלו\" דווקא! ודוחים: מכאן אין ראיה גמורה, שכן יש לומר כי \u0003איידי\u0004 \u0005[על ידי,\u0006 מתוך\u0005]\u0006 ש\u0003לא נסיב ברישא\u0004 \u0005[הביא בראשה]\u0006 של משנה זו \u0003\"יוצא מהן\" לא נסיב נמי בסיפא\u0004 \u0005[הביא גם כן בסופה]\u0006 \u0003\"יוצא מהן\",\u0004 אף שגם בהם הוא מותר, ואין לדייק מהעדרה של הזכרה זו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו ש\u0003אמר ר' יהודה: מעשה ואסר ר' טרפון עלי ביצים שנתבשלו עמו,\u0004 עם הבשר. \u0003אמרו לו: אימתי —\u0004 \u0003בזמן שאמר \"בשר זה עלי\", שהנודר מן הדבר ונתערב באחר, ויש בו בנותן טעם\u0004 מן הדבר שנדר ממנו — \u0003הרי זה אסור.\u0004 ומכאן שממה שאסר דבר מסויים עליו (\"זה\", \"אלו\") — נאסר ביוצא ממנו.","ומסבירים: \u0003ב\"אלו\" לא קא מיבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 ש\u0003דוקא הוא,\u0004 ולשון זו ודאי מספיקה לאסור את היוצא ממנו. \u0003כי מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה, היה זה האם \u0003ב\"שאיני טועם\" דוקא,\u0004 האם אף לשון זו לבדה קובעת איסור ביוצא ממנו, \u0003או לאו דוקא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003\"דג דגים שאיני טועם\" —\u0004 \u0003אסור בהן,\u0004 בדגים, \u0003בין\u0004 שהם \u0003גדולים בין\u0004 שהם \u0003קטנים, בין חיים בין מבושלים, ומותר בטרית טרופה ובציר.\u0004 משמע שהביטוי \"שאיני טועם\" אינו אוסר גם את הציר היוצא מהן.","\u0003אמר רבא:\u0004 אין מכאן הוכחה, כיון שאפשר לפרש \u0003וכבר יצא מהן.\u0004 שאין מדובר שם בציר שיצא מן הדגים לאחר שאסר אותם על עצמו, אלא בציר שיצא קודם לכן, והציר הזה לא נכלל בלשון \"דגים\" שנדר בה. ואם כן, אין פתרון מלא לשאלתו של רמי בר חמא."],["\u0003הנודר מן התמרים —\u0004 \u0003מותר בדבש תמרים.\u0004 הנודר \u0003מסתוניות\u0004 (ענבים מאוחרים וחמוצים) — \u0003מותר בחומץ סתוניות. ר' יהודה בן בתירא אומר: כל ששם תולדתו קרויה עליו,\u0004 שהדבר היוצא ממנו עדיין נושא את שמו של המקור ממנו בא, כגון \"דבש תמרים\" \"חומץ סתוניות\", \u0003ונודר\u0004 אדם \u0003הימנו\u0004 מן המקור — \u0003אסור\u0004 אף \u0003ביוצא הימנו. וחכמים מתירים,\u0004 שלדעתם אינו נאסר אלא במה שאסר עליו.","שואלים: והרי שיטת \u0003[חכמים]\u0004 המתירים \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנה, האומר שהנודר מן התמרים מותר בדבש תמרים, ומה ההבדל ביניהם?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 בין שיטת התנא קמא לשיטת חכמים, הבדל למעשה לענין \u0003הדא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלל זה אמר ר' שמעון בן אלעזר: כל\u0004 מאכל \u0003שדרכו לאכול\u0004 אותו, \u0003ודרך היוצא ממנו,\u0004 מאותו מאכל, \u0003לאכול\u0004 אף אותו, \u0003כגון תמרים ודבש תמרים,\u0004 אם \u0003נדר בו —\u0004 \u0003אסור\u0004 גם \u0003ביוצא ממנו,\u0004 ואם \u0003נודר מיוצא ממנו —\u0004 \u0003אסור\u0004 גם \u0003בו\u0004 עצמו.","אבל \u0003כל\u0004 מאכל \u0003שאין דרכו לאכול\u0004 אותו בעצמו, \u0003ו\u0004רק \u0003דרך היוצא ממנו לאכול,\u0004 אם \u0003נודר בו —\u0004 \u0003אין אסור אלא ביוצא ממנו, שלא נתכוון זה אלא ליוצא ממנו.\u0004 שתנא קמא אינו מחלק בין דבר שדרכו להיאכל ובין דבר שאין דרכו להיאכל, ואם נדר בו — מתיר את היוצא ממנו בכל מקרה. וחכמים שבסוף המשנה סבורים כשיטת ר' שמעון בן אלעזר, שאם נדר בדבר שאין דרכו להיאכל הריהו מותר בו עצמו ונאסר דווקא ביוצא ממנו, כגון חומץ סתוניות. אבל הנודר מן התמרים, שדרכם להיאכל, אסור לשיטתם בין בתמרים בין בדבש.","\u0003הנודר מן היין —\u0004 \u0003מותר ביין תפוחים,\u0004 שסתם יין הוא יין ענבים. הנודר \u0003מן השמן —\u0004 \u0003מותר בשמן שומשמין,\u0004 שסתם שמן הוא שמן זיתים. הנודר \u0003מן הדבש —\u0004 \u0003מותר בדבש תמרים,\u0004 שסתם דבש הוא דבש דבורים.","הנודר \u0003מן החומץ —\u0004 \u0003מותר בחומץ סתוניות,\u0004 שסתם חומץ נעשה מיין. הנודר \u0003מן הכרישין —\u0004 \u0003מותר בקפלוטות\u0004 (מין כרישים). הנודר \u0003מן הירק —\u0004 \u0003מותר בירקות השדה\u0004 (הגדלים בר בשדות), \u0003שהוא שם לוויי\u0004 הבא להגדיר ירקות מיוחדים אלה, וכיון שיש לו שם לוואי איננו בכלל סתם אותו דבר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר מן השמן,\u0004 אם נדר \u0003בארץ ישראל —\u0004 \u0003מותר בשמן שומשמין, ואסור בשמן זית,\u0004 שסתם שמן בארץ ישראל שמן זית הוא. \u0003ו\u0004אם נדר \u0003בבבל —\u0004 \u0003אסור בשמן שומשמין,\u0004 משום שבבבל סתם שמן נעשה משומשמים, \u0003ומותר בשמן זית\u0004 שהוא נדיר שם, ובודאי לא התכוון אליו. \u0003מקום שמסתפקין\u0004 (משתמשים) \u0003מזה ומזה —\u0004 \u0003אסור בזה ובזה.\u0004","על המשפט האחרון תוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא במקרה \u0003דרובא\u0004 \u0005[שרוב]\u0006 בני המקום \u0003מן חד\u0004 \u0005[מ\u0006מין \u0005אחד]\u0006 הם \u0003מסתפקין. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003איזיל בתר רובא\u0004 \u0005[נלך אחר הרוב]\u0006 ונתיר את השמן האחר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003ספק איסורא לחומרא\u0004 \u0005[איסור לחומרה]\u0006 ויש להחמיר ולאסור אפילו כשרק מיעוט משתמש בסוג האחר.","שנינו בברייתא: \u0003הנודר מן הירק, בשאר שני שבוע\u0004 (באחת משש השנים הראשונות ממחזור שבע שנות השמיטה) — \u0003אסור בירקות הגינה, ומותר בירקות השדה\u0004 הצומחים בר בשדה. \u0003וב\u0004שנת ה\u0003שביעית,\u0004 להיפך — \u0003אסור בירקות השדה\u0004 משום שסתם ירקות שאוכלים אז הם ירקות שדה, \u0003ומותר בירקות הגינה\u0004 לפי שאסור לעבוד את האדמה בשנה זו, ואין ירקות גינה מצויים. \u0003אמר ר' אבהו משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל:\u0004"],["\u0003לא שנו\u0004 שמותר בירקות גינה בשביעית \u0003אלא במקום שאין מביאין ירק מחוצה לארץ לארץ,\u0004 ואז הכל משתמשים בשביעית רק בירקות השדה. \u0003אבל במקום שמביאין ירק מחוצה לארץ לארץ,\u0004 שאין שביעית נוהגת בחוץ לארץ — \u0003אסור\u0004 גם בירקות גינה בשנה השביעית.","ומעירים: הרי זה \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 בענין זה: \u0003אין מביאין ירק מן חוצה לארץ לארץ, ר' חנניה בן גמליאל אומר: מביאין ירק מחוצה לארץ לארץ.\u0004 ושואלים: \u0003מאי טעמיה דמאן דאמר\u0004 \u0005[מה טעמו של מי שאומר]\u0006 \u0003אין מביאין? אמר ר' ירמיה:\u0004 חוששים \u0003משום גוש\u0004 אדמה של אדמת העמים שהיא מטמאה, שלא יביאו אותו יחד עם הירקות לארץ ישראל, ויגרום בה טומאה.","הנודר \u0003מן הכרוב —\u0004 \u0003אסור באיספרגוס\u0004 שהוא מין כרוב, אבל הנודר \u0003מן האיספרגוס —\u0004 \u0003מותר בכרוב.\u0004","הנודר \u0003מן הגריסין\u0004 (פול שגורסים, שוברים לחתיכות) — \u0003אסור במקפה\u0004 (מרק עבה שעושים מגריסים), \u0003ור' יוסי מתיר.\u0004 ולכל הדעות הנודר \u0003מן המקפה —\u0004 \u0003מותר בגריסין\u0004 עצמן. הנודר \u0003מן המקפה —\u0004 \u0003אסור בשום\u0004 שבתוכה שהוא חלק מהמרכיבים של המקפה, \u0003ור' יוסי מתיר.\u0004 הנודר \u0003מן השום —\u0004 \u0003מותר במקפה.\u0004","הנודר \u0003מן העדשים —\u0004 \u0003אסור באשישים\u0004 שהם מיני מאכל הנעשים מעדשים, ו\u0003ר' יוסי מתיר.\u0004 והכל מודים שהנודר \u0003מן האשישים מותר בעדשים.\u0004 אמר \u0003\"\u0004קונם \u0003חטה חטין שאני טועם\" —\u0004 \u0003אסור בהן\u0004 בחיטים \u0003בין\u0004 בצורת \u0003קמח בין הפת\u0004 שנאפתה מהן. אמר \u0003\"\u0004קונם \u0003גריס גריסין שאני טועם\" —\u0004 \u0003אסור בהן בין חיין בין מבושלין. ר' יהודה אומר:\u0004 אם אומר \u0003\"קונם גריס או חטה שאני טועם\" מותר לכוס\u0004 (לכסוס, לכרסם אותם) כשהם \u0003חיים\u0004 (בלתי מבושלים), משום שאין דרכם להיאכל כך, ולא על דעת כן נדר.","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון בן גמליאל אומר:\u0004 אמר \u0003\"חטה שאני טועם\" —\u0004 \u0003אסור לאפות\u0004 ולאכול פת מקמח חטה, \u0003ומותר לכוס\u0004 (לכסוס, לכרסם) חטה. אמר \u0003\"חטים שאני טועם\" —\u0004 \u0003אסור לכוס ומותר לאפות,\u0004 כי לשון זו מתייחסת דווקא לחיטים בגרגריהן. \u0003\"חטה חטין שאני טועם\" —\u0004 \u0003אסור בין לכוס בין לאפות.\u0004","וכן, אם אמר \u0003\"גריס שאני טועם\" —\u0004 \u0003אסור לבשל,\u0004 שכך נקרא תבשיל של גריסים, \u0003ומותר לכוס,\u0004 לכרסם אותם כשהם חיים. אמר \u0003\"גריסין שאני טועם\" —\u0004 \u0003אסור לכוס ומותר לבשל. \"גריס גריסין שאני טועם\" —\u0004 \u0003אסור בין לבשל בין לכוס.\u0004",""],["\u0003הנודר מן הירק —\u0004 \u0003מותר בדלועין\u0004 שאין אנשים כוללים אותם בלשונם בכלל ירק, \u0003ור' עקיבא אוסר. אמרו לו\u0004 חכמים \u0003לר' עקיבא: והלא אומר אדם לשלוחו \"קח לי ירק\", והוא,\u0004 השליח, חוזר ו\u0003אומר\u0004 למשלח \u0003\"לא מצאתי אלא דלועין\".\u0004 משמע שאין הדלועים בכלל ירק!","\u0003אמר להם: כן הדבר,\u0004 שמדבר זה עצמו מביא אני ראיה לשיטתי, \u0003או שמא אומר הוא \"לא מצאתי אלא קיטנית\"? אלא\u0004 מכאן, \u0003שהדלועין בכלל ירק\u0004 למרות היותם נבדלים משאר ירקות, ומשום כך אומר השליח שלא מצא אלא דלועים, \u0003וקיטנית אינו בכלל ירק\u0004 כלל, ומשום כך אין השליח אומר למשלחו שמצא קיטנית, כיון שאינו מין ירק כלל. \u0003ואסור\u0004 הנודר מן הירק \u0003בפול המצרי לח\u0004 שעדיין הוא בגדר ירק, \u0003ומותר ביבש\u0004 שאינו נקרא ירק.","שנינו במשנה: \u0003הנודר מן הירק\u0004 — מותר בדלועים, ור' עקיבא אוסר. ותוהים על דברי ר' עקיבא: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מן ירק נדר!\u0004 ואיך אפשר לכלול בכך את הדלועים שהם פרי (האדמה), ואינם ירק? \u0003אמר עולא: באומר \"ירקי קדרה עלי\",\u0004 ודלועים אף הם בכלל הירקות שמבשלים בקדירה. ושואלים: אם כך הוא אומר — \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003ירק הנאכל בקדרה קאמר\u0004 \u0005[הוא אומר]\u0006, וכוונתו לירק שנאכל אגב דברים אחרים ולא הניחוהו בקדירה אלא כדי להוסיף טעם לתבשיל? ומשיבים: \u0003באומר \"ירק המתבשל בקדרה עלי\",\u0004 ודלועים בכלל זה.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005חלוקים]\u0006 במשנתנו ר' עקיבא וחכמים? ומסבירים: \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003כל מילתא\u0004 \u0005[דבר]\u0006 ש\u0003צריך שליחא לאמלוכי עלה\u0004 \u0005[השליח להימלך עליו] —\u0006 \u0003לאו מיניה\u0004 \u0005[לא מינו]\u0006 \u0003הוא,\u0004 ולכן כיון שצריך השליח לשאול אם גם הדלועים בכלל — משמע שאינם מין ירק. \u0003ור' עקיבא סבר: כל מילתא דמימליך שליחא עלה\u0004 \u0005[כל דבר שנמלך השליח עליו] —\u0006 \u0003מיניה\u0004 \u0005[מינו]\u0006 \u0003הוא,\u0004 שאינו הולך להימלך על דבר שאינו מינו. \u0003אמר אביי: מודה ר' עקיבא לענין מלקות, שאינו לוקה\u0004 שאף אם אכל דלועים אין זה נחשב עובר ממש על נדרו, כיון שאין הדבר ברור לגמרי.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003השליח שעשה שליחותו\u0004 ששלחו בעל הבית להשתמש באיזה חפץ, ושכח שאותו חפץ הוא של הקדש, אם עשה השליח את שליחותו כתיקונה — \u0003בעל הבית מעל,\u0004 שהרי השליח עשה את הדבר עבור בעל הבית. אם \u0003לא עשה שליחותו,\u0004 אלא שינה ממנה — \u0003שליח מעל.\u0004 שכן על ידי שינוי בשליחותו שוב אינו נחשב כשליחו של בעל הבית, אלא כעושה את הדבר לעצמו.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסובר סברה זו? \u0003אמר רב חסדא: מתניתין\u0004 \u0005[\u0006אותה \u0005משנה]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' עקיבא\u0004 במשנה שלנו. וראיה לדבר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 אחרת: \u0003כיצד\u0004 הוא ענין זה של שליח שעשה או לא עשה שליחותו? \u0003אמר לו\u0004 המשלח לשליח: \u0003\"תן בשר לאורחים\" ונתן להם\u0004 השליח \u0003כבד,\u0004 או אמר לו \u0003\"תן כבד\" ונתן להם בשר —\u0004 \u0003השליח מעל,\u0004 משום ששינה משליחותו. \u0003ואי\u0004 \u0005[ואם]\u0006 לדעת \u0003ר' עקיבא —\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' עקיבא: כל מילתא דמימליך עלה\u0004 \u0005[כל דבר שנמלך עליו]\u0006 ה\u0003שליח —\u0004 \u0003מיניה\u0004 \u0005[מינו]\u0006 \u0003הוא,\u0004 ובודאי כבד הוא בכלל בשר לענין זה, ואם כן \u0003למעול\u0004 \u0005[שימעל]\u0006 \u0003בעל הבית ולא למעול\u0004 ה\u0003שליח,\u0004 שהרי עשה שליחותו!","\u0003אמר אביי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שאותה משנה היא כדעת \u0003ר' עקיבא,\u0004"],["\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודה ר' עקיבא\u0004 ש\u0003צריך\u0004 השליח \u0003אימלוכי\u0004 \u0005[להימלך]\u0006 על כל פנים? וכיון שלא נמלך ועשה מדעת עצמו אין זה נקרא עושה שליחותו. \u0003איתמר שמעתא קמיה\u0004 \u0005[נאמרה הלכה זו\u0006 כולה \u0005לפני]\u0006 \u0003רבא. אמר להון\u0004 \u0005[להם]\u0006 למוסרי הדברים: \u0003שפיר\u0004 \u0005[יפה]\u0006 \u0003אמר נחמני,\u0004 הוא אביי.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[החולק עליו]\u0006 על \u0003ר' עקיבא\u0004 במשנה? ומשיבים: \u0003רבן שמעון בן גמליאל היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנודר מן הבשר —\u0004 \u0003אסור בכל מיני בשר, ואסור\u0004 גם \u0003בראש וברגלים ובקנה ובכבד ובלב,\u0004 למרות שלא היו אנשים אוכלים אותם כרגיל. \u0003ו\u0004כן אסור \u0003בעופות,\u0004 שאף הם בכלל \"בשר\" בלשון בני אדם. \u0003ומותר בבשר דגים וחגבים,\u0004 לפי שאינם נקראים \"בשר\".","\u0003רבן שמעון בן גמליאל אומר: הנודר מן הבשר\u0004 — \u0003אסור בכל מיני בשר, ומותר בראש וברגלים ובקנה ובכבד ובלב ובעופות, ואין צריך לומר בשר דגים וחגבים. וכן היה רבן שמעון בן גמליאל אומר: קרביים לאו\u0004 \u0005[אינם]\u0006 נחשבים \u0003בשר, ואוכליהן לאו בר אינש\u0004 \u0005[אינו\u0006 נחשב \u0005בן אדם]\u0006 שאין זה מאכל אדם. ומסבירים את כוונתו: \u0003אוכליהן\u0004 מבחינת דיני אכילתם כגון לענין נדרים אמנם \u0003כבשר\u0004 הם, אבל \u0003לענין זביני\u0004 \u0005[קניה],\u0006 אם הולך לקנות אותם, \u0003לאו בר אינש\u0004 \u0005[אינו בן אדם].\u0006 ומכל מקום למדנו מכאן שרבן שמעון בן גמליאל חולק על ר' עקיבא, שהרי אף שכבד הוא בכלל הדברים ששליח נמלך בשולחו עליהם אם לא מצא בשר, מכל מקום לדעתו אין הוא בכלל בשר לענין נדרים.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003בשר עוף ל\u0004דעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003דאסיר\u0004 \u0005[שאסור]\u0006 והוא בכלל בשר — משום \u0003דעביד שליחא דמימליך עליה\u0004 \u0005[שעשוי השליח להימלך עליו]\u0006 ולומר לשולחו שלא מצא בשר אלא עופות. ואולם \u0003בשר דגים נמי עביד שליחא\u0004 \u0005[גם כן עשוי השליח]\u0006 להימלך עליו, \u0003דאי לא משכח בישרא, מימליך עליה\u0004 \u0005[שאם אינו מוצא בשר, נמלך עליו]\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 לשולחו: \u0003אי לא משכחנא בישרא, אייתי\u0004 \u0005[אם אינני מוצא בשר, אביא]\u0006 \u0003דגים? וליתסרו\u0004 \u0005[ושייאסרו]\u0006 גם הדגים ומדוע פשוט לתנא שעוף הוא בכלל בשר, ודגים אינם בכלל בשר?","\u0003אמר אביי:\u0004 כאן מדובר \u0003כגון שהקיז דם\u0004 בשעת הנדר, \u0003דלא אכיל\u0004 \u0005[שאינו אוכל]\u0006 \u0003דגים,\u0004 שמקובל היה בידם שהם מזיקים אחר הקזת דם. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם במקרה זה אתה מדבר, \u0003אפילו עופות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אכיל\u0004 \u0005[אינו אוכל].\u0006 ש\u0003אמר שמואל: דמסוכר ואכיל בישרא דצפרא\u0004 \u0005[\u0006מי \u0005שמקיז\u0006 דם \u0005ואוכל\u0006 אחרי כן \u0005בשר ציפור] —\u0006 \u0003פרח לביה כצפרא\u0004 \u0005[פורח ליבו כציפור],\u0006 משמע שאין הדבר יפה לגוף! \u0003ו\u0004כן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מקיזין לא על דגים,\u0004 כלומר, לאחר הקזה אין אוכלים דגים, \u0003ולא על עופות, ולא על בשר מליח. ו\u0004עוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003הקיז דם —\u0004 \u0003לא יאכל לא חלב, ולא גבינה, ולא ביצים, ולא שחליים, ולא עופות, ולא בשר מליח!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 בשר של \u0003עופות\u0004 ש\u0003אפשר\u0004 לאוכלו אחר הקזה \u0003על ידי שליקה\u0004 (בישול מרובה), וכשמבשלו היטב אינו מזיק.","\u0003אביי אמר:\u0004 כאן מדובר \u0003כגון דכייבין ליה עיניה\u0004 \u0005[שכואבות לו עיניו]\u0006 ש\u0003דגים קשין לעינים,\u0004 ומשום כך דווקא דגים מותרים ולא עופות. ומקשים: להיפך, \u0003אי הכי אכיל\u0004 \u0005[אם כך\u0006 הריהו \u0005אוכל]\u0006 \u0003דגים, דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר שמואל:\u0004 ונתן סימן לדבר בצירוף האותיות הסמוכות: \u0003נו\"ן סמ\"ך עי\"ן,\u0004 שהוא כראשי תיבות: \u0003נונא סמא\u0004 \u0005[הדג סם,\u0006 תרופה\u0005]\u0006 \u0003לעינים!\u0004 ומשיבים: \u0003ההוא\u0004 שאמר שמואל מדובר ב\u0003סוף אוכלא\u0004 \u0005[דלקת\u0006 העיניים\u0005]\u0006 שאז יפים הדגים, אבל לא בתחילת הדלקת."],["\u0003הנודר מן הדגן —\u0004 \u0003אסור בפול המצרי יבש\u0004 שאף הוא נקרא דגן, אלו \u0003דברי ר' מאיר. וחכמים אומרים: אינו אסור אלא בחמשת המינין\u0004 של דגן (חיטה, שעורה, שיבולת שועל, כוסמת ושיפון) בלבד. \u0003ר' מאיר אומר: הנודר מן התבואה —\u0004 \u0003אינו אסור אלא מחמשת המינין, אבל הנודר מן הדגן —\u0004 \u0003אסור בכל\u0004 ואף בפול המצרי היבש וכיוצא בו, \u0003ומותר בפירות האילן ובירק.\u0004","מדברי ר' מאיר האומר כי הנודר מן הדגן אסור בכל, \u0003למימרא\u0004 \u0005[\u0006אפשר להסיק ו\u0005לומר]\u0006 ש\u0003\"דגן\" כל\u0004 דבר \u0003דמידגן\u0004 \u0005[שנדגן],\u0006 שנאסף בבת אחת ועושים אותו כרי \u0003משמע. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף:\u0004 נאמר לאחר שקרא המלך חזקיהו לעם לתת את המעשר והתרומה כראוי: \u0003\"וכפרץ הדבר הרבו בני ישראל [ראשית] דגן תירוש ויצהר\u0004 ודבש \u0003וכל תבואת שדה\u0004 ומעשר הכל \u0003לרב\u0004 הביאו\u0003\"\u0004 (דברי הימים ב לא, ה), \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003\"דגן\" —\u0004 \u0003כל דמידגן\u0004 \u0005[שנדגן]\u0006 \u0003משמע, מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"כפרץ הדבר הרבו\"?\u0004 שמכאן משמע שמלבד דגן תירוש ויצהר הוסיפו להביא עוד דברים שאינם חייבים במעשר מדין תורה. ואם \"דגן\" כולל כל דבר שנדגן, אם כן מה נוסף ב\"כל תבואת השדה\"? \u0003אמר אביי:\u0004 דבר זה לא בא אלא \u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003פירות האילן וירק\u0004 שאין עושים מהם כרי, ואף מהם הפרישו מעשר.","שנינו במשנה ש\u0003ר' מאיר אומר: הנודר מן התבואה\u0004 אינו אסור אלא בחמשת המינים, אבל הנודר מן הדגן אסור בכל. \u0003אמר ר' יוחנן: הכל מודים בנודר מן התבואה שאין אסור אלא מחמשת המינין\u0004 ובזה לא נחלקו חכמים על ר' מאיר. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שוין בנודר מן התבואה שאין אסור אלא מחמשת המינין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי אלה הם הקרויים תבואה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003\"תבואה\" כל מילי\u0004 \u0005[\u0006ה\u0005דברים]\u0006 \u0003משמע,\u0004 כלומר, כל יבול שמוציאה האדמה, על כן \u0003קמשמע לן דלא משמע\u0004 \u0005[השמיע לנו שאין משמעות]\u0006 הביטוי \u0003כל מילי\u0004 \u0005[\u0006ה\u0005דברים].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף:\u0004 הלא נאמר \u0003\"וכפרץ הדבר הרבו בני ישראל...\u0004 וכל תבואת שדה \u0003\",\u0004 וכפי שהסברנו הביטוי \"תבואת השדה\" בא לרבות את כל הדברים הגדלים בשדה! \u0003אמר רבא,\u0004 צריך לחלק: \u0003\"תבואה\" לחוד,\u0004 כלומר, סתם תבואה משמעה רק מיני הדגן, \u0003\"תבואת שדה\" לחוד\u0004 ובכלל זה גם שאר יבולי האדמה.","מסופר: \u0003בר\u0004 \u0005[בנו]\u0006 של \u0003מר שמואל פקיד דליתנון תליסר אלפי זוזי\u0004 \u0005[ציווה שיתנו שלושה עשר אלפי זוזים]\u0006 \u0003לרבא מן עללתא\u0004 \u0005[היבול]\u0006 של נכסיו שב\u0003נהר פניא. שלחה רבא\u0004 את הבעיה הזו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: \"עללתא\" היכי מיקריא\u0004 \u0005[איך\u0006 היא \u0005נקראת],\u0006 מה נכלל בהגדרה של \"עללתא\"? \u0003אמר רב יוסף: מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא: ושוין בנודר מן התבואה שאין אסור אלא מחמשת המינין,\u0004 משמע שתבואה היא רק חמשת המינים, ולזה התכוון הנותן, וכמו כן ב\"עללתא\". \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003\"תבואה\" לא משמע אלא מחמשת המינין, \"עללתא\"\u0004 שפירושה יבול — \u0003כל מילי\u0004 \u0005[\u0006ה\u0005דברים]\u0006 \u0003משמע.\u0004","\u0003אהדרוהו לקמיה\u0004 \u0005[החזירוהו,\u0006 הביאו את כל הדיון הזה \u0005לפני]\u0006 \u0003רבא. אמר: הא\u0004 \u0005[זה]\u0006 \u0003לא קא מיבעיא\u0004 \u0005[היה מסופק]\u0006 \u0003לי\u0004 ש\u0003\"עללתא\" —\u0004 \u0003כל מילי\u0004 \u0005[\u0006ה\u0005דברים]\u0006 הגדלים \u0003משמע.\u0004 אלא \u0003הדא\u0004 \u0005[זה]\u0006 \u0003הוא דאיבעיא\u0004 \u0005[שנסתפק]\u0006 \u0003לי: שכר בתים ושכר ספינות מאי\u0004 \u0005[מה]\u0006 דינו? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דפחתן, לאו עללתא היא\u0004 \u0005[ש\u0006הם \u0005פוחתים, אין זה\u0006 נקרא \u0005יבול].\u0006 כי יבול אפשר לקרוא לפירות או לרווחים הבאים ונוספים תדיר. אבל בתים וספינות, כיון שהם נפחתים עם השימוש בהם, שמה נאמר כי מאחר והריוח מהם כולל בתוכו את דמי הפחת, אין זה בכלל יבול. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא ידיע פחתייהו עללתא היא\u0004 \u0005[שאין ידוע,\u0006 ניכר, \u0005הפחת שלהם\u0006 הם נקראים גם כן \u0005יבול].\u0006 \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב יוסף\u0004 את תגובתו של רבא. \u0003אמר\u0004 רב יוסף בתרעומת: \u0003וכי מאחר\u0004 ש\u0003לא צריך לן\u0004 \u0005[אותנו]\u0006 והוא סבור שיודע את התשובה בעצמו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003שלח לן\u0004 \u0005[לנו]\u0006 לשאול? \u0003איקפד\u0004 \u0005[הקפיד]\u0006 \u0003רב יוסף\u0004 על כך.","\u0003שמע רבא\u0004 שהוא מקפיד, \u0003ואתא לקמיה במעלי יומא דכפורי\u0004 \u0005[ובא לפניו בערב יום הכיפורים]\u0006 כדי לפייסו. \u0003אשכחיה לשמעיה דהוה קא מזיג קמיה כסא דחמרא\u0004 \u0005[מצא את שמשו\u0006 של רב יוסף \u0005שהיה מוזג לפניו כוס יין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לשמש: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את הכוס \u0003דאמזיג ליה אנא\u0004 \u0005[שאמזוג לו אני].\u0006 \u0003יהב ליה, וקא מזיג איהו כסא דחמרא\u0004 \u0005[נתן לו\u0006 השמש, \u0005ומזג הוא,\u0006 רבא, \u0005כוס יין].\u0006 \u0003כי קא שתי\u0004 \u0005[כאשר שתה]\u0006 רב יוסף את היין \u0003אמר: הדין מיזגא דמי למיזגא\u0004 \u0005[מזיגה זו דומה למזיגה]\u0006 של \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר חמא\u0004 שהיה מוזג יותר מים ממה שהיו שאר אנשים מוזגים. שהיה רב יוסף עיוור ולא ראה את רבא כשנכנס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הוא ניהו\u0004 \u0005[זה הוא]\u0006 כלומר, אני עצמי הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לרבא: \u0003לא תיתיב אכרעך עד דאמרת לי פירושא דהדין מילתא\u0004 \u0005[אל תשב על רגליך עד שתאמר לי פירושו של דבר זה]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וממדבר מתנה וממתנה נחליאל ומנחליאל במות\"\u0004 (במדבר כא, יח-יט)?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: כך יש כך לדורשו: \u0003כיון שעושה אדם את עצמו כמדבר, שהוא מופקר לכל\u0004 — אז \u0003תורה ניתנה לו במתנה, שנאמר: \"וממדבר מתנה\". וכיון שניתנה לו במתנה —\u0004 \u0003נחלו אל,\u0004 עושה אותו ה' נחלה לו, \u0003שנאמר: \"וממתנה נחליאל\". כיון שנחלו אל —\u0004 \u0003עולה לגדולה, שנאמר: \"ומנחליאל במות\". ואם הגביה עצמו\u0004 ונתגאה בתורתו — \u0003הקדוש ברוך הוא משפילו, שנאמר: \"ומבמות הגיא\"\u0004 (במדבר כא, כ), \u0003ולא עוד אלא ששוקעין אותו בקרקע, שנאמר: \"ונשקפה על פני הישימן\"\u0004 (במדבר כא, כ). \u0003ואם חוזר בו\u0004 מגאוותו — \u0003הקדוש ברוך הוא מגביהו\u0004"],["\u0003שנאמר: \"כל גיא ינשא\"\u0004 (ישעיה מ, ד). וכששמע רב יוסף דברים אלה הבין שרבא מכיר בטעותו, שנראה כמתגאה על רבו, ומרגיש שצריך להכניע עצמו לפניו, ונתפייס.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר מן הדגן —\u0004 \u0003אסור אף בפול המצרי יבש, ומותר\u0004 בו \u0003ב\u0004עודו \u0003לח. ומותר באורז,\u0004 וכן \u0003בחילקא, בטרגיס ובטיסני\u0004 (מיני גריסים מגרגירי חטה). \u0003הנודר מן פירות השנה —\u0004 \u0003אסור בכל פירות\u0004 האדמה והעץ הצומחים באותה \u0003השנה, ומותר בגדיים ובטלאים ובחלב ובביצים ובגוזלות\u0004 שנולדו באותה שנה, לפי שאינם נקראים \"פירות\" סתם. \u0003ואם אמר \"גידולי שנה\u0004 זו אסורים \u0003עלי\" —\u0004 \u0003אסור בכולן.\u0004","\u0003הנודר מן פירות הארץ —\u0004 \u0003אסור בכל פירות\u0004 הצומחים מן \u0003הארץ, ומותר בכמהין ופטריות\u0004 שאינם נקראים \"פירות הארץ\". \u0003ואם אמר \"גידולי קרקע עלי\" —\u0004 \u0003אסור בכולן.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה: \u0003על דבר שאין גידולו מן הארץ אומר \"שהכל נהיה בדברו\", ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003על המלח ועל הזמית\u0004 (מין מרק) \u0003ועל כמהין ופטריות אומר \"שהכל נהיה בדברו\".\u0004 משמע שכמהים ופטריות אינם נקראים גידולי קרקע! \u0003אמר אביי: מירבא רבו מארעא\u0004 \u0005[גדלים,\u0006 צומחים הם בפועל \u0005מן הארץ]\u0006 אבל \u0003מינק מאוירא ינקי\u0004 \u0005[לינוק, מן האויר\u0006 הם \u0005יונקים]\u0006 \u0003ולא מארעא\u0004 \u0005[מן הארץ].\u0006 ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 שם \u0003\"על דבר שאין גידולו מן הארץ\"\u0004 ובכללם כמהים ופטריות, ואיך ניתן לומר שכמהים ופטריות גידולם מן הארץ! ומשיבים: \u0003תני\u0004 \u0005[שנה,\u0006 ותקן\u0005]\u0006 באותה משנה: \u0003על דבר שאין יונק מן הארץ.\u0004","\u0003הנודר מן הכסות —\u0004 \u0003מותר ב\u0004לבישת \u0003שק,\u0004 \u0003וביריעה, ובחמילה\u0004 (מין יריעה גסה) שאינם בכלל כסות רגילה. \u0003אמר \"קונם צמר עולה עלי\" —\u0004 \u0003מותר\u0004 לו \u0003להתכסות בגיזי צמר\u0004 כיון שאינם בכלל מלבוש, ואינו אסור אלא באריג של צמר. וכן אם אמר \u0003\"\u0004קונם \u0003הפשתן עולה עלי\" —\u0004 \u0003מותר להתכסות באניצי פשתן\u0004 (פשתן שלא נטווה), שלא נתכוון אלא ללבישת אריג של פשתן.","\u0003ר' יהודה אומר: הכל\u0004 מתפרש \u0003לפי הנודר:\u0004 אם \u0003טען\u0004 (נשא) מטען של צמר ופשתים \u0003והזיע, והיה ריחו קשה\u0004 (לא נוח) לו, ומתוך כך \u0003אמר \"קונם צמר ופשתים עולה עלי\" —\u0004 \u0003מותר להתכסות\u0004 בבגדי צמר ופשתן, \u0003ואסור להפשיל לאחוריו\u0004 כמשא, לפי שבשעת הנדר היתה כוונתו לנשיאת צמר ופשתן ולא ללבישתם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003הנודר מן הכסות —\u0004 \u0003מותר בשק וביריעה ובחמילה, ואסור בפונדא\u0004 (חגורה רחבה) \u0003ובפסקיא\u0004 (חגורה) \u0003ובסקורטיא ובקטבליא\u0004 (מלבושי עור) \u0003ואנפליא\u0004 (גרביים של עור) \u0003ופליניא\u0004 (סינור עור) \u0003ומכנסים וכובע.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"איסקורטי\"\u0004 שהוזכרה כאן? \u0003אמר רבה בר חנה:\u0004 הכוונה היא ל\u0003כיתונא דצלא\u0004 \u0005[כותנות של עור]\u0006.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003יוצאין\u0004 בשבת לרשות הרבים \u0003בשק עבה ובסגוס עבה וביריעה ובחמילה מפני הגשמים\u0004 ואין הם נחשבים כמשא שנושא בשבת, אלא כמיני לבוש, \u0003אבל לא בתיבה ולא בקופה ולא במחצלת\u0004 להגן \u0003מפני הגשמים,\u0004 שאין אלה נחשבים כלבוש אלא כמשא. \u0003הרועים יוצאין\u0004 בשבת \u0003בשקים\u0004 שעליהם, שכך דרכם לצאת, \u0003ולא רועים בלבד אמרו אלא כל אדם\u0004 מותר לצאת בהם, \u0003אלא שדברו חכמים בהווה\u0004 (במציאות הרגילה) שבדרך כלל נוהגים כך רועים.","שנינו במשנה: \u0003ר' יהודה אומר הכל לפי הנודר כו'. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003כיצד אמר ר' יהודה הכל לפי הנודר?\u0004 אם \u0003היה לבוש צמר, והצר\u0004 והציק לו הבגד, \u0003ו\u0004מתוך כך \u0003אמר \"קונם צמר עולה עלי\",\u0004 במקרה כזה — \u0003אסור ללבוש ומותר לטעון\u0004 עליו אריגי צמר. ולהיפך, אם \u0003היה טעון פשתן והזיע, ואמר \"קונם פשתן עולה עלי\" —\u0004 במקרה כזה \u0003מותר ללבוש ואסור לטעון.\u0004 שמפרשים את דבריו לפי המצב והטעם שבו נדר."],["\u0003הנודר מן הבית —\u0004 \u0003מותר בעלייה\u0004 (קומה שניה של הבית), אלו \u0003דברי ר' מאיר. וחכמים אומרים: עלייה בכלל הבית\u0004 נחשבת, ואסור גם בה. אבל \u0003הנודר מן עלייה —\u0004 \u0003מותר בבית,\u0004 שאין בית בכלל עלייה.","שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה לגבי הלכות נגעים, שהכתוב \u0003\"\u0004כנגע נראה לי \u0003בבית\"\u0004 (ויקרא יד, לה) בא \u0003לרבות את היציע,\u0004 שהוא כעין מחצית קומה שבבית, ועוד, \u0003\"בבית\" —\u0004 \u0003לרבות את העלייה? אמר רב חסדא:\u0004 שיטת \u0003ר' מאיר היא, דאי רבנן\u0004 \u0005[שאם\u0006 שיטת \u0005חכמים]\u0006 היא, \u0003האמרי רבנן\u0004 \u0005[הרי אמרו חכמים]\u0006 כי \u0003עלייה בכלל הבית,\u0004 ואם כן \u0003למה לי קרא\u0004 \u0005[כתוב]\u0006 מפורש \u0003\"בבית\" לריבויא\u0004 \u0005[לרבות\u0006 אותה\u0005]?\u0006","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 מכל מקום \u0003בעיא קרא\u0004 \u0005[צריכה\u0006 לענין זה \u0005כתוב]\u0006 מפורש. כיון \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 \u0003\"בבית ארץ אחזתכם\"\u0004 (ויקרא יד, לד) \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפרשת נגעי בתים, והייתי אומר: מה \u0003דמחבר בארעא\u0004 \u0005[שמחובר בארץ] —\u0006 \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003בית, עלייה —\u0004 \u0003הא לא מחבר בארעא\u0004 \u0005[הרי אינה מחוברת בארץ],\u0006 והייתי סבור שאינה נטמאת למרות שהיא בכלל הבית, ולכן דרוש הריבוי אפילו לדעת חכמים.","ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 מן החכמים \u0005הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב הונא בר חייא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא:\u0004 אם אומר לו המוכר לקונה \u0003\"בית בביתי אני מוכר לך\" —\u0004 \u0003מראהו עלייה,\u0004 ויכול לטעון שזה הוא מה שמכר לו. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"בית שבביתי אני מוכר לך\", אבל\u0004 אם מכר לו \u0003\"בית\" סתם —\u0004 \u0003אינו מראהו עלייה\u0004 אלא את הבית עצמו. \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי הלכה זו שאמר עולא, דעת \u0003ר' מאיר\u0004 במשנתנו \u0003היא\u0004 שאין העלייה בכלל בית? ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש המלה \u0003\"עלייה\"\u0004 באותו ענין — \u0003מעולה שבבתים\u0004 ולא עלייה ממש, ולכן כשאומר לו \"בית שבביתי\" כוונתו לבית מיוחד, לחלק הטוב ביותר בבית.","\u0003הנודר מן המטה —\u0004 \u0003מותר בדרגש\u0004 שאינו בכלל מיטה בלשון בני אדם, אלו \u0003דברי ר' מאיר. וחכמים אומרים: דרגש בכלל מטה.\u0004 אבל לדברי הכל \u0003הנודר מן הדרגש —\u0004 \u0003מותר במטה.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 טיבו של \u0003דרגש\u0004 זה? \u0003אמר עולא: ערסא דגדא\u0004 \u0005[מיטת מזל],\u0006 שהיו שמים בבית מיטה לשם מזל בלבד, ואין אדם ישן עליה. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לעולא: הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כשהן מברין אותו\u0004 את המלך בשעת אבלו, \u0003כל העם מסובין על הארץ והוא מיסב על הדרגש.\u0004 ואם כדבריך, \u0003כולא שתא לא יתיב עלה\u0004 \u0005[כל השנה אינו יושב עליה]\u0006 על מיטה מיוחדת זו, \u0003ההוא יומא יתיב עלה\u0004 \u0005[אותו יום\u0006 של אבל \u0005יושב עליה]?\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על קושיה זו \u0003רבינא:\u0004 הרי זה \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 הדין לגבי \u0003בשר ויין, דכולה שתא\u0004 \u0005[שכל השנה]\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה] —\u0006 \u0003אכיל\u0004 \u0005[אוכל]\u0006 את אלה \u0003ואי בעי\u0004 \u0005[ואם רוצה] —\u0006 \u0003לא אכיל\u0004 \u0005[אינו אוכל],\u0006 ואילו \u0003ההוא יומא אנן יהבינן ליה\u0004 \u0005[אותו יום\u0006 של אבל \u0005אנו נותנים לו]\u0006 בסעודת הבראה בשר ויין דווקא! ואם כן אין זה קושי.","\u0003אלא הא קשיא\u0004 \u0005[זו\u0006 היא ש\u0005קשה]\u0006 עליו; \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003דרגש\u0004 שבבית \u0003לא היה\u0004 האבל \u0003כופהו\u0004 (הופכו) כדרך שצריך לעשות בכל המיטות שבבית האבל, \u0003אלא\u0004 רק \u0003זוקפו\u0004 (מעמידו) על צידו. \u0003ואי אמרת ערסא דגדא\u0004 \u0005[ואם אתה אומר\u0006 שדרגש, \u0005מיטת מזל]\u0006 \u0003הוא, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכופה את מטתו\u0004 מחמת אבלו — \u0003לא מטתו\u0004 שלו \u0003בלבד הוא כופה, אלא כל מטות שיש לו בתוך הבית הוא כופה\u0004 גם אם אינו ישן בהן, ומדוע לא יכפה גם את הדרגש? ודוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006"],["\u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 הדין האמור \u0003אמטה\u0004 \u0005[על מיטה]\u0006 \u0003המיוחדת לכלים, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 : \u0003אם היתה\u0004 בבית האבל \u0003מטה המיוחדת לכלים\u0004 ואינה מיועדת לשינה — \u0003אין צריך לכפותה.\u0004 ואף מיטת מזל זו, כיון שאין ישנים עליה — אינה צריכה כפייה.","\u0003אלא אי קשיא\u0004 \u0005[אם קשה] —\u0006 \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: דרגש\u0004 אין האבל כופה אותו אלא \u0003מתיר קרביטיו\u0004 (לולאות המחזיקות את המצע) \u0003והוא נופל מאליו. ואי\u0004 \u0005[ואם]\u0006 \u0003דרגש ערסא דגדא\u0004 \u0005[מיטת מזל]\u0006 \u0003הוא, קרביטין מי אית ליה\u0004 \u0005[האם יש לו]\u0006? הרי אין במיטה זו לולאות כלל! \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר: שאילתיה\u0004 \u0005[שאלתיו]\u0006 מהו דרגש \u0003לההוא מרבנן\u0004 \u0005[לאחד החכמים]\u0006 \u0003ורב תחליפא בר מערבא שמיה\u0004 \u0005[שמו]\u0006 \u0003דהוה שכיח בשוקא דצלעי\u0004 \u0005[שהיה מצוי בשוק\u0006 מוכרי \u0005העורות],\u0006 \u0003ואמר לי: מאי\u0004 \u0005[מהו]\u0006 \u0003דרגש —\u0004 \u0003ערסא דצלא\u0004 \u0005[מיטה של עור]\u0006.","\u0003איתמר\u0004 \u0005[נאמר]\u0006, \u0003איזהו מטה ואיזהו דרגש? אמר ר' ירמיה: מטה —\u0004 \u0003מסרגין אותה על גבה\u0004 שקושרים את הסירוג המחזיק את המצע על גבי מוטות המיטה, \u0003דרגש —\u0004 \u0003מסרגין אותו מגופו\u0004 שהסירוג נקשר בחורים המצויים בתוך המוט של המיטה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003כלי עץ מאימתי\u0004 נחשבים ככלים גמורים הראויים להיות \u0003מקבלין טומאה? המטה והעריסה —\u0004 \u0003משישופם בעור הדג,\u0004 שהיו משפשפים בו את העץ כדי להחליקו. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מטה מסתרגת על גבה, למה לי שיפת עור הדג?\u0004 הרי בין כה וכה אין העץ של המיטה נראה לעין!","\u0003אלא\u0004 צריך לומר כי \u0003הא והא\u0004 \u0005[זה וזה],\u0006 מיטה ודרגש, סירוגם \u0003מגופן\u0004 של המוטות, וההבדל ביניהם הוא כך: \u0003מטה —\u0004 \u0003אעולי ואפוקי בבזיני\u0004 \u0005[מכניסים ומוציאים\u0006 את הסירוג \u0005בנקבים\u0006 שבמוטות\u0005]\u0006, \u0003דרגש —\u0004 \u0003אעולי ואפוקי באבקתא\u0004 \u0005[מכניסים ומוציאים בלולאות\u0006 הקשורות למוטות\u0005]\u0006 וזהו שאמר רבן שמעון בן גמליאל כי כשמתירים את הלולאות נופל הסירוג.","\u0003אמר ר' יעקב בר אחא אמר רבי: מטה שנקליטיה\u0004 (שני מוטות העולים על גבה) \u0003יוצאין\u0004 וגבוהים, אי אפשר לכפותה מפני שהנקליטים בולטים ויוצאים בחוץ, אלא \u0003זוקפה\u0004 על צדה, \u0003ודיו\u0004 בכך. \u0003אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כרבן שמעון בן גמליאל\u0004 בענין כפיית דרגש.","\u0003הנודר מן העיר —\u0004 \u0003מותר ליכנס לתחומה\u0004 (תחום שבת) \u0003של עיר\u0004 שהוא בתוך אלפיים אמה מן העיר, \u0003ואסור ליכנס לעיבורה\u0004 בתוך שבעים אמה הקרובות לעיר. \u0003אבל הנודר מן הבית —\u0004 \u0003אסור\u0004 רק \u0003מן האגף\u0004 (מקום הגפת הדלת) \u0003ולפנים.\u0004","שואלים: \u0003מנלן דעיבורא דמתא כמתא דמי\u0004 \u0005[מניין לנו שעיבורה של עיר כעיר\u0006 עצמה הוא \u0005נחשב]\u0006? \u0003אמר ר' יוחנן,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויהי בהיות יהושע ביריחו\" וגו'\u0004 (יהושע ה, יג), ויש לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ביריחו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביריחו ממש —\u0004 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויריחו סגרת ומסגרת\u0004 מפני בני ישראל אין יוצא ואין בא\u0003\"\u0004 (יהושע ו, א)! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהיה \u0003בעיבורה\u0004 של העיר, ואף שלא היה ביריחו ממש נאמר עליו שהיה בתוכה.","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אפילו\u0004 הנמצא \u0003בתחומה\u0004 של העיר נחשב כאילו הוא בעיר, ויהושע היה בתחום העיר יריחו ונחשב לו הדבר כאילו היה ביריחו עצמה! ודוחים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003בתחומה\u0004 של עיר \u0003\"ומדתם מחוץ לעיר\u0004... אלפיים באמה\u0003\"\u0004 (במדבר לה, ה), משמע שתחומה של העיר נחשב מחוץ לעיר, ולא כעיר עצמה.","שנינו במשנה: \u0003הנודר מן הבית אינו אסור אלא מן האגף ולפנים.\u0004 ומדייקים: \u0003אבל מן האגף ולחוץ,\u0004 כל שהוא מחוץ למקום הגפת הדלת — \u0003לא. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב מרי:\u0004 נאמר בהלכות נגעים \u0003\"ויצא הכהן מן הבית\u0004 אל פתח הבית והסגיר את הבית\u0003\"\u0004 (ויקרא יד, לח), ושאלו במדרש ההלכה: \u0003יכול ילך\u0004 הכהן \u0003לביתו ויסגיר\u0004 משם את הבית בתורת בית המנוגע בצרעת — \u0003תלמוד לומר: \"אל פתח הבית\"\u0004 (ויקרא יד, לח). \u0003אי\u0004 \u0005[אם]\u0006 \u0003אל פתח הבית, יכול יעמוד תחת המשקוף ויסגיר —\u0004 \u0003תלמוד לומר: \"\u0004ויצא הכהן \u0003מן הבית\", עד שיצא מן הבית כולו.\u0004","\u0003הא כיצד? עומד\u0004 בחוץ \u0003בצד המשקוף ויסגיר. ומנין שאם הלך לביתו והסגיר, או שעמד תחת השקוף\u0004 (המשקוף) \u0003והסגיר שהסגירו מוסגר\u0004 בדיעבד — \u0003תלמוד לומר: \"והסגיר את הבית\"\u0004 (ויקרא יד, לח), \u0003מכל מקום.\u0004 משמע שגם מחוץ לדלת, כל זמן שהוא מתחת למשקוף — נחשב כנמצא בתוך הבית! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר \u0003גבי בית\u0004 המנוגע, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"\u0004ויצא הכהן \u0003מן הבית\"\u0004 וכוונתו \u0003עד שיצא מן הבית כולו.\u0004"],["\u0003א משנה\u0004 האומר \u0003\"קונם פירות האלו עלי\",\u0004 או \u0003\"קונם הן על פי\",\u0004 או \u0003\"קונם הן לפי\" —\u0004 \u0003אסור\u0004 לא רק בהן, אלא גם \u0003בחילופיהן,\u0004 אם החליף אותם בדבר אחר, \u0003ובגידוליהן\u0004 אם זרעם וצמח מהם דבר. אם אמר \u0003\"\u0004קונם פירות אלה \u0003שאני אוכל\",\u0004 או \u0003\"שאני טועם\" —\u0004 \u0003מותר בחילופיהן ובגידוליהן.\u0004 ובאיזה גידולים אמרו שמותר — \u0003בדבר שזרעו כלה\u0004 שכאשר זורעים אותו, הזרע עצמו כלה. \u0003אבל בדבר שאין זרעו כלה,\u0004 כגון מיני פקעות שמצמיחות מתוכן ואינן כלות — \u0003אפילו גידולי גידולין אסורין,\u0004 שהרי נשאר גופו של האיסור במקומו.","\u0003האומר לאשתו\u0004 \u0003\"קונם מעשה ידיך עלי\",\u0004 או \u0003\"קונם הן על פי\" \"קונם הן לפי\" —\u0004 \u0003אסור\u0004 גם \u0003בחילופיהן ובגידוליהן\u0004 של מעשה ידיה. אבל אם אמר לאשתו \u0003\"\u0004קונם \u0003שאני אוכל\",\u0004 או \u0003\"שאני טועם\u0004 ממעשה ידיך \u0003\"\u0004— \u0003מותר בחילופיהן ובגידוליהן,\u0004 ואלו גידולים מותרים — \u0003בדבר שזרעו כלה. אבל דבר שאין זרעו כלה —\u0004 \u0003אפילו גידולי גידולין אסורין.\u0004","אם אמר \u0003\"\u0004את הדברים \u0003שאת עושה איני אוכל עד הפסח\",\u0004 או שאמר \u0003\"\u0004דברים \u0003שאת עושה איני מתכסה\u0004 בהם \u0003עד הפסח\", עשתה\u0004 את הדברים \u0003לפני הפסח —\u0004 \u0003מותר לאכול\u0004 אותם \u0003ולהתכסות\u0004 בהם \u0003אחר הפסח.\u0004 אבל אם היה נדרו בנוסח \u0003\"\u0004הדברים \u0003שאת עושה עד הפסח איני אוכל\",\u0004 או \u0003\"\u0004מה \u0003שאת עושה עד הפסח איני מתכסה\"\u0004 — דברים ש\u0003עשתה לפני הפסח אסור לאכול ולהתכסות\u0004 בהם אפילו \u0003אחר הפסח.\u0004 אמר לה \u0003\"\u0004קונם \u0003שאת נהנית לי עד הפסח אם הולכת את לבית אביך עד החג\"\u0004 (חג הסוכות). אם \u0003הלכה לפני הפסח\u0004 — חל הנדר, ו\u0003אסורה בהנאתו עד הפסח.\u0004"],["\u0003לאחר הפסח —\u0004 נמצא שעברה \u0003ב\"בל יחל\",\u0004 שהרי התקיים התנאי ועברה על הנדר. האומר לאשתו \u0003\"שאת נהנית לי עד החג אם הולכת את לבית אביך עד הפסח\"\u0004 אם \u0003הלכה לפני הפסח —\u0004 \u0003אסורה בהנאתו עד החג, ומותרת לילך אחר הפסח\u0004 שזה לא היה כלול בתנאי שהתנה עימה.","שנינו במשנה: \u0003האומר לאשתו \"קונם מעשה ידיך עלי\",\u0004 או שאומר \u0003\"קונם הן על פי\",\u0004 או \u0003\"קונם הן לפי\" וכו', ישמעאל איש כפר ימא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 \u0003איש כפר דימא, העלה בידו\u0004 בעיה ביחס ל\u0003בצל שעקרו\u0004 מן האדמה \u0003ב\u0004שנה ה\u0003שביעית\u0004 (שמיטה) ויש עליו כל דיני קדושת שביעית, \u0003ונטעו בשמינית, ורבו גידוליו\u0004 של השנה השמינית \u0003על עיקרו\u0004 של השנה השביעית. \u0003והכי קא מיבעיא ליה\u0004 \u0005[וכך נשאלה לו]\u0006 : כיון ש\u0003גידוליו היתר,\u0004 שהרי צמחו בשנה השמינית, \u0003ועיקרו אסור\u0004 משום שנת השמיטה, האם לומר \u0003כיון\u0004 ש\u0003רבו גידוליו\u0004 יותר \u0003מעיקרו, אותן גידולי היתר מעלין\u0004 (מבטלים) \u0003את\u0004 חלק \u0003האיסור\u0004 שבבצל, \u0003או לא? אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 ושאלו, ו\u0003לא הוה בידיה\u0004 \u0005[היה בידו]\u0006 פתרון.","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יצחק נפחא, פשט\u0004 \u0005[פתר]\u0006 \u0003ליה מן הדא\u0004 \u0005[לו מזו]\u0006 ש\u0003אמר ר' חנינא תריתאה אמר ר' ינאי: בצל של תרומה שנטעו, ורבו גידוליו על עיקרו —\u0004 \u0003מותר,\u0004 שגידוליו מבטלים את עיקרו, ואף כאן, מבטלים גידולי השמינית את העיקר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה\u0004 לר' יצחק נפחא, \u0003ואיתימא\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 שאמר זאת \u0003ר' זריקא: שביק מר תרין ועביד כחד\u0004 \u0005[מניח אדוני שנים ועושה כ\u0006דעת \u0005אחד]?!\u0006","ושואלים: \u0003מאן נינהו תרין\u0004 \u0005[מי הם השנים]\u0006 הללו שאינם סוברים כן? ומפרטים: ש\u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 גפן \u0003ילדה\u0004 (צעירה) שעדיין היא ערלה \u0003שסיבכה\u0004 (הרכיב אותה) \u0003ב\u0004תוך גפן \u0003זקינה\u0004 שהיא מותרת, \u0003ובה\u0004 בגפן הצעירה \u0003פירות, אף על פי שהוסיפה\u0004 פי \u0003מאתים\u0004 ממה שהיה בה קודם לכן, ומה שהוסיפה היה מן ההיתר, שהרי היא יונקת מן הגפן הזקינה, בכל זאת \u0003אסור,\u0004 ואין הגידולים המותרים מבטלים את העיקר האסור במאתיים כדין ערלה, מכיון שהפירות היו אסורים מתחילתם.","\u0003ו\u0004כן \u0003אמר ר' שמואל בר ר' נחמני אמר ר' יונתן: בצל שנטעו בכרם\u0004 ונאסר משום כלאי הכרם, \u0003ו\u0004אחר כך \u0003נעקר הכרם\u0004 וגדל הבצל הרבה בהיתר — בכל זאת הבצל \u0003אסור.\u0004 ונמצא שר' יוחנן ור' יונתן שניהם חולקים על ר' ינאי, ואין פתרון פשוט לשאלה זו.","\u0003הדר אתא\u0004 \u0005[חזר\u0006 ו\u0005בא]\u0006 ישמעאל איש כפר ימא \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אמי ופשיט ליה מן הדא\u0004 \u0005[ופשט,\u0006 פתר, \u0005לו\u0006 את הבעיה \u0005מזו]\u0006 ש\u0003אמר ר' יצחק אמר ר' יוחנן: ליטרא בצלים שתיקנה\u0004 (הפריש ממנה תרומות ומעשרות) \u0003ו\u0004אחר כך \u0003זרעה,\u0004 כאשר גדל ויוצא ממנה יבול \u0003מתעשרת לפי כולה,\u0004 שמפרישים מן הכל מעשר. שאף שהבצלים שזרע עדיין קיימים, ואותם כבר עישר, מכל מקום כיון שרבו הגידולים על העיקר הריהם מבטלים את העיקר, והכל נחשב כטבל. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אותן גידולין מבטלין\u0004 את ה\u0003עיקר.\u0004","ודוחים: מכאן אין להוכיח, כי \u0003דלמא לחומרא שאני\u0004 \u0005[שמא להחמיר שונה]\u0006 הדבר, ואנו חוששים שמא גידולים מבטלים את העיקר לחייבו במעשר על הכל, אבל שיהיו גידולים מבטלים את העיקר להיתר — לא למדנו.","\u0003אלא\u0004 יש להביא מקור אחר, \u0003מן הדא דתניא\u0004 \u0005[מזו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004"],["\u0003כל דבר\u0004 אסור \u0003שיש לו מתירין,\u0004 כלומר, שיש דרך להתירו, \u0003כגון טבל\u0004 שמתירים אותו על ידי עישורו, \u0003ומעשר שני\u0004 שמתירים אותו על ידי פדייתו או בהעלאתו לירושלים, \u0003והקדש\u0004 שאפשר לפדותו, \u0003וחדש,\u0004 תבואה חדשה, שמותרת לאחר הבאת העומר — \u0003לא נתנו בהן חכמים שיעור\u0004 לביטולם, אם נפלו לתוך תערובת של היתר, ואינם בטלים בכל שיעור שהוא. \u0003וכל דבר שאין לו מתירין, כגון תרומה ותרומת מעשר וחלה וערלה וכלאי הכרם —\u0004 \u0003נתנו בהם חכמים שיעור\u0004 לביטולם.","\u0003אמרו לו\u0004 לר' שמעון: \u0003והלא שביעית אין לה\u0004 לפירותיה \u0003מתירין, ו\u0004בכל זאת \u0003לא נתנו בה חכמים שיעור. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השביעית אוסרת כל שהוא במינה\u0004 (אם האיסור וההיתר שבתערובת מאותו מין)! \u0003אמר להן: אף אני לא אמרתי\u0004 שתהא שביעית אוסרת, הן על ידי תערובת, והן על ידי גידולי שביעית שנוספו על עיקר של היתר \u0003אלא ל\u0004ענין \u0003ביעור\u0004 פירות שביעית, שניתן לאכול את התערובת רק קודם שהגיע הזמן לבערם מן העולם. שכיון שמותרים באותה שעה הרי זה כדבר שיש לו מתירים.","\u0003אבל ל\u0004ענין היתר \u0003אכילה\u0004 לאחר זמן הביעור שאז אין עוד היתר לגידולי השביעית — יש להם שיעור לביטולם, ואוסרים את התערובת רק \u0003ב\u0004שיעור כזה שהאיסור \u0003נותן טעם\u0004 בתערובת. ולענייננו אפשר ללמוד מכאן שגידולים מבטלים את העיקר! ודוחים: \u0003ודלמא הא נמי לחומרא שאני\u0004 \u0005[ושמא זו גם כן להחמיר שונה],\u0006 שהחמירו שגם על העיקר של היתר תחול קדושת שביעית, אבל אין ללמוד מכאן גם לקולא, שיתירו גידולים את העיקר!","\u0003אלא מן הדא פשטה\u0004 \u0005[מזו פתר אותה]\u0006 את שאלת ר' ישמעאל איש כפר ימא, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בצלים\u0004 של השנה השישית \u0003שירדו עליהם גשמים\u0004 בשנה השביעית \u0003וצמחו, אם היו עלין שלהן שחורין\u0004 (ירוקים כהים) שמכאן מוכח שיש בזה גידול של ממש, הריהם \u0003אסורין\u0004 כגידולי שביעית. אם \u0003הוריקו\u0004 (התבהרו, הצהיבו) העלים ונראים כמושים — \u0003מותרין\u0004 שנחשב הכל כגידולי השנה השישית.","\u0003ר' חנניא בן אנטיגנוס אומר:\u0004 יש סימן אחר לדבר, \u0003אם יכולין ליתלש ב\u0004אמצעות ה\u0003עלין שלהן,\u0004 משמע שהעלים חזקים ובריאים ואז \u0003אסורין. וכנגדן\u0004 במקרה דומה לזה, אם היה זה בצל של שביעית שצמח \u0003למוצאי שביעית,\u0004 כלומר, בשנה השמינית — \u0003מותרין\u0004 הבצלים. ונדייק: \u0003למימרא\u0004 \u0005[לומר,\u0006 ללמוד\u0005]\u0006 מכאן ש\u0003גידולי היתר מעלין\u0004 (מבטלים) \u0003את האיסור.\u0004 ודוחים: \u0003ודלמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003במדוכנין,\u0004 בבצלים שדך וכתש את עיקרם, ונמצא שהעיקר כבר בטל, שהרי אינו ניתן לשימוש. ומפני זה מותר, ולא משום שגידולי ההיתר ביטלו את האיסור.","\u0003אלא מן הדא\u0004 \u0005[מזו]\u0006 יש לפתור, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003המנכש\u0004 (מוציא עשבים רעים) \u0003עם הכותי\u0004 (שומרוני) \u0003בחסיות\u0004 (צמחים בעלי פקעות או בצלים) — \u0003אוכל מהן אכילת עראי\u0004 בלי לעשרן, כדרך שמותר לאכול כל טבל אכילת ארעי, \u0003ו\u0004כאשר נאספו לערימה וצריך לעשרן — \u0003מעשרן ודאי\u0004 ולא בתורת דמאי (ספק מעושר), שאין מניחים שהכותי עישר את החסיות.","\u0003ר' שמעון בן אלעזר אומר: אם\u0004 היו החסיות של \u0003ישראל\u0004 ה\u0003חשוד על השביעית\u0004 ויש לחשוש שמא זרען בשביעית, \u0003למוצאי שביעית —\u0004 \u0003מותר\u0004 לנכש עמו, ואין חוששים שמא יש בהן עוד קדושת שביעית. ומדייקים: \u0003למימרא\u0004 \u0005[\u0006האם יש \u0005לומר,\u0006 ללמוד\u0005]\u0006 מכאן ש\u0003גידולי היתר\u0004 של השנה השמינית \u0003מעלין\u0004 (מבטלים) \u0003את האיסור,\u0004 ולכן אין חוששים. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר פה \u0003בדבר שזרעו כלה?\u0004 ודוחים: \u0003הא תניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אלו הן חסיות —\u0004 \u0003כגון הלוף השום והבצלים,\u0004 וכל אלה הם דברים שאין זרעם כלה.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר גם כאן \u0003במדוכנין\u0004 שכתש קודם את העיקר? ומשיבים: הלא \u0003\"חשוד על השביעית\" קתני\u0004 \u0005[שנה],\u0006 ואם הוא חשוד — משמע שזרע אותם כדרכם. ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר פה \u0003בתערובת\u0004 שנתערבו החסיות בחסיות של היתר ובטלו ברוב, ולכן הן מותרות? ומשיבים: \u0003המנכש קתני\u0004 \u0005[שנה]\u0006 שכשהוא מנכש את החסיות נוטלן אחת אחת ואוכלן, ולא הספיקו להתערב עם אחרים.","ואומרים: אם כן לפי זה \u0003לימא תיהוי תיובתיה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהיה\u0006 זו, תשובתם, \u0005קושיה חמורה]\u0006 על \u0003ר' יוחנן ור' יונתן\u0004 שאמרו לענין ערלה וכלאי הכרם שאין גידולי היתר מעלים את האיסור! \u0003אמר ר' יצחק: שניא\u0004 \u0005[שונה]\u0006 \u0003שביעית, הואיל ואיסורה על ידי קרקע —\u0004 \u0003בטילתה\u0004 (ביטולה) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003על ידי קרקע.\u0004 שכיון שחוזרת וגדילה בקרקע בהיתר, הרי היא מתבטלת בכך.","ומקשים: \u0003הרי מעשר\u0004 ש\u0003איסורו\u0004 גם כן \u0003על ידי קרקע, ואין בטילתו על ידי קרקע. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ליטרא מעשר\u0004 ראשון \u0003טבל\u0004 (שלא הפריש ממנה תרומת מעשר) \u0003שזרעה בקרקע, ו\u0004עכשיו \u0003השביחה\u0004 (גדילה) \u0003והרי היא\u0004 בשיעור של \u0003כעשר ליטרין —\u0004 \u0003חייבת\u0004 התוספת \u0003במעשר ובשביעית. ואותה ליטרא\u0004 ראשונה שזרעה בקרקע \u0003מעשר עליה ממקום אחר,\u0004 ולא ממנה עצמה, \u0003לפי חשבון\u0004 תרומת מעשר שהיא חייבת. הרי שלמרות שזרע את המעשר בקרקע, לא בטל ממנו האיסור על ידי הגידולים!"],["\u0003אמרי\u0004 \u0005[אומרים]\u0006 : ב\u0003מעשר\u0004 לא הקרקע היא הגורמת את החיוב, אלא \u0003דיגון,\u0004 צבירת היבול לכרי, \u0003הוא דקא גרים ליה\u0004 \u0005[שגורם לו]\u0006 את החיוב, שרק עם הדיגון נקבעה חובת הפרשת המעשרות מן התבואה, ומשום שאין החיוב תלוי בקרקע, אף אין יורד החיוב על ידי זריעה בקרקע.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רמי בר חמא\u0004 ממה ששנינו במשנתנו: האומר \u0003\"קונם פירות האלו עלי\",\u0004 או \u0003\"קונם הן על פי\",\u0004 או \u0003\"קונם הן לפי\" —\u0004 \u0003אסור בחילופיהן ובגידוליהן.\u0004 ואם אמר \u0003\"\u0004קונם פירות אלו \u0003שאני אוכל\",\u0004 או \u0003\"שאני טועם\" —\u0004 \u0003מותר בחילופיהן ובגידוליהן בדבר שזרעו כלה, אבל בדבר שאין זרעו כלה —\u0004 \u0003אפילו גידולי גידולין אסורין.\u0004 ונמצא איפוא שאין הגידולים מבטלים את האיסור!","\u0003אמר ר' אבא: שאני\u0004 \u0005[שונים]\u0006 \u0003קונמות הואיל ואי בעי מתשיל עלייהו\u0004 \u0005[ואם\u0006 הוא \u0005רוצה\u0006 יכול \u0005להישאל עליהם]\u0006 ולהתירם, ולכן \u0003הוו להו\u0004 \u0005[הריהם]\u0006 \u0003כדבר שיש לו מתירין, ואין בטיל ברוב.\u0004","ומקשים: \u0003והרי תרומה\u0004 שגם בה \u0003דאי בעי מיתשיל עלה\u0004 \u0005[שאם רוצה\u0006 יכול \u0005להישאל עליה]\u0006 כמו לגבי נדר, שיכול ללכת לחכם, ולומר שהוא מבטל את מה שקבע והפריש דבר מסויים כתרומה, \u0003ו\u0004בכל זאת \u0003בטלי\u0004 \u0005[בטלים]\u0006 \u0003ברוב. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 : \u0003סאה תרומה טמאה שנפלה לפחות ממאה\u0004 סאים של \u0003חולין —\u0004 \u0003תרקב,\u0004 שאין לתערובת זו תקנה. שכיון שתרומה טמאה אסורה באכילה לכל אדם — אוסרת היא אף את מה שנתערבה בו, להיות כמותה. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם נפלה \u0003למאה\u0004 סאים ויותר של חולין — \u0003תעלה\u0004 (תיבטל)! ומשיבים, \u0003אמרי\u0004 \u0005[אומרים]\u0006 : כאן \u0003בתרומה\u0004 שהיא \u0003ביד כהן עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003לא מצי מיתשיל עלה\u0004 \u0005[יכול\u0006 הבעלים \u0005להישאל עליה]\u0006 ולהתיר אותה. אבל כל זמן שהיא ביד הבעלים יכול להישאל עליה, ואינה בטילה.","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: \u0003אם היתה\u0004 התרומה שנפלה ונתערבה \u0003טהורה —\u0004 \u0003תמכר\u0004 כל התבואה \u0003לכהן,\u0004 והכהן ינהג בה כאילו היתה כולה תרומה, והוא מותר באכילת תרומה טהורה. משמע שמדובר בתרומה שעדיין היא ברשות הבעלים ולא בידי הכהן! \u0003אלא\u0004 יש לומר ש\u0003בישראל שנפלו לו\u0004 נכסים בירושה \u0003מבית אבי אמו כהן עסקינן\u0004 \u0005[עוסקים אנו]\u0006, שהוא ירש את התרומה שקיבל אבי אמו הכהן, ותרומה זו שייכת מבחינה ממונית לנכד, אף כי הוא עצמו אינו יכול לאכול אותה וצריך למוכרה לכהן.","על הסבר זה מקשים: \u0003[והא] קתני סיפא\u0004 \u0005[והרי שנה\u0006 ב\u0005סופה\u0006 של אותה משנה\u0005]\u0006 : \u0003תימכר לכהן חוץ מדמי אותה סאה\u0004 של תרומה שנתערבה, כי סאת התרומה היא עצמה שייכת לכהן. ואם מדובר כאן ביורש שיש לו זכות בעלות על התרומה מדוע אינו מוכר לכהן גם את אותה סאה? והרי יש לו עצמו זכות בה!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותרץ באופן אחר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003קונמות מצוה לאיתשולי עליהן\u0004 \u0005[להישאל עליהם]\u0006 ולהתירם, \u0003משום\u0004 דבריו של \u0003ר' נתן.\u0004 ש\u0003אמר ר' נתן: כל הנודר —\u0004 \u0003כאילו בנה במה, והמקיימו\u0004 את הנדר של עצמו — \u0003כאילו מקטיר עליה,\u0004 על אותה במה. אולם \u0003תרומה מאי\u0004 \u0005[מה]\u0006 \u0003מצוה לאיתשולי עלה\u0004 \u0005[להישאל עליה]\u0006? וזה הוא טעם ההבדל בין דין קונמות הנחשבים כדבר שיש לו מתירים, לתרומה שאינה נחשבת כדבר שיש לו מתירים.","\u0003גופא,\u0004 לגופה של הלכה שהוזכרה קודם, \u0003אמר ר' יוחנן: ליטרא בצלים שתיקנה\u0004 (הפריש כל מעשרותיה) \u0003וזרעה —\u0004 \u0003מתעשרת לפי כולה,\u0004 כלומר, לפי כל כמות הפירות ולא רק לפי כמות הגידולים. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבה וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזו]\u0006. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: מאן צאית\u0004 \u0005[מי שומע]\u0006 \u0003לך ולר' יוחנן רבך! היתר שבהן להיכן הלך?\u0004 הרי הליטרה שזרע היתה מותרת שהרי הפריש עליה מעשרות, ומדוע צריך לעשר את הכל? מן הראוי היה להפחית את הסאה הראשונה המתוקנת, שעליה לא יצטרך לעשר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן דכוותה\u0004 \u0005[שנינו\u0006 במשנה \u0005כמותה]\u0006 : \u0003בצלים\u0004 של השנה השישית \u0003שירדו עליהם גשמים\u0004 בשנה השביעית \u0003וצימחו,\u0004"],["\u0003אם היו עלין שלהן שחורין\u0004 (ירוקים כהים) שמכאן מוכח שיש בזה גידול של ממש — \u0003אסורין\u0004 הבצלים, ואם \u0003הוריקו\u0004 (הבהירו, הצהיבו) העלים ונראים כמושים — \u0003מותרין. וכי\u0004 \u0005[וכאשר]\u0006 הם \u0003שחורין אמאי\u0004 \u0005[מדוע]\u0006 \u0003אסורין? לימא\u0004 \u0005[נאמר]\u0006 גם כאן: \u0003היתר שבהן להיכן הלך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003על עיקר קתני\u0004 \u0005[שנה],\u0006 שהבצלים עצמם אסורים? — \u0003אתוספת קתני\u0004 \u0005[על תוספת\u0006 העלים שצמחו \u0005שנה]\u0006 שהם \u0003אסורין.\u0004 ושואלים: \u0003אי הכי מאי אתא\u0004 \u0005[אם כך מה בא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]\u0006 כאשר חלק על דין זה? \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: הגדל בחיוב —\u0004 \u0003חייב, הגדל בפטור —\u0004 \u0003פטור.\u0004 הלא ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003נמי הכי\u0004 \u0005[גם כן כך]\u0006 \u0003אמר!\u0004","ודוחים, זו אינה קושיה; יש לפרש כי \u0003כולה מתניתין\u0004 \u0005[כל משנתנו\u0006 זו\u0005]\u0006 \u0003רבן שמעון בן גמליאל קתני לה\u0004 \u0005[שנה אותה].\u0006 \u0003ו\u0004מכל מקום אין להקשות מכאן על רבה, שכן \u0003עד כאן לא שמעת ליה\u0004 \u0005[אותו]\u0006 \u0003לרבן שמעון בן גמליאל\u0004 שאומר שאין העיקר בטל אלא במקום ש\u0003לא קא טרח\u0004 \u0005[טורח]\u0006 והדבר גדל מעצמו, \u0003אבל היכא דקא טרח\u0004 \u0005[במקום שטורח]\u0006 ועושה מעשה של זריעה או נטיעה — \u0003בטיל ברובא\u0004 \u0005[ברוב].\u0006","ומקשים: \u0003וכל היכא דקא טרח\u0004 \u0005[מקום שהוא טורח]\u0006 \u0003בטיל ברובא\u0004 \u0005[ברוב]?\u0006 \u0003והרי ליטרא מעשר טבל\u0004 שזרעו, \u0003דקטרח\u0004 \u0005[שהוא טורח]\u0006 בזריעתו, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003ואותה ליטרא מעשר עליו ממקום אחר לפי חשבון\u0004 ואינה בטילה בגידולים! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003גבי מעשר\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"עשר תעשר\u0004 את כל תבואת זרעך היוצא השדה\u0003\"\u0004 (דברים יד, כב), שאף הזרע שזרעת הוא בכלל התבואה. \u0003והיתירא\u0004 \u0005[והיתר] —\u0006 \u0003זרעי אינשי\u0004 \u0005[זורעים אנשים],\u0006 \u0003איסורא\u0004 \u0005[איסור] —\u0006 \u0003לא זרעי אינשי\u0004 \u0005[זורעים אנשים],\u0006 שאנשים זורעים כרגיל תבואה שכבר עושרה, ואם זרע דבר שלא תוקן — קנסו אותו שיעשר אף מה שהתחייב לעשר מתחילה.","\u0003גופא,\u0004 לגופה של הלכה שהוזכרה קודם, ש\u0003אמר ר' חנינא תירתאה אמר ר' ינאי: בצל של תרומה שנטעו, ורבו גידוליו על עיקרו —\u0004 \u0003מותר. למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 וללמוד ש\u0003גידולי\u0004"],["\u0003היתר מעלין את האיסור? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003גידולי תרומה —\u0004 \u0003תרומה\u0004 ובודאי שאינם מבטלים את העיקר! ומשיבים: \u0003בגידולי גידולין קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שהם מותרים. שאין מדובר כאן במה שגדל במישרין מן התרומה, אלא בגידולים שצמחו מגידולים אלה, ואותם התיר ר' ינאי. ומקשים: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו]:\u0006 \u0003גידולי גידולין\u0004 של תרומה הרי הם \u0003חולין!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003אפילו בדבר שאין זרעו כלה,\u0004 כגון בצלים — גידולי גידולים מותרים. ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הטבל —\u0004 \u0003גידוליו מותרין בדבר שזרעו כלה. אבל דבר שאין זרעו כלה —\u0004 \u0003גידולי גידולין אסורין,\u0004 ולפי זה היו אף גידולי הגידולים של תרומה זו צריכים להיות אסורים! ומשיבים: \u0003רבויא\u0004 \u0005[ריבוי\u0006 וגידול\u0005]\u0006 ש\u0003רבו גידולין על עיקרו מותר קא משמע לן\u0004 \u0005[השמיע לנו].\u0006","","","האומר \u0003\"קונם יין שאני טועם היום\" —\u0004 \u0003אינו אסור אלא עד\u0004 סוף אותו יום, עד \u0003שתחשך,\u0004 ולא עשרים וארבע שעות (\"מעת לעת\"). האומר: \u0003\"\u0004קונם יין שאני טועם \u0003שבת\u0004 (שבוע) \u0003זו\" —\u0004 \u0003אסור בכל השבת\u0004 (השבוע), \u0003ושבת שעברה\u0004 שאם נדר ביום השבת עצמו, הריהו בכלל איסור זה, למרות שהשבת נחשבת כשבוע שעבר. האומר \u0003\"חדש זה\" —\u0004 \u0003אסור בכל החדש, וראש חדש\u0004 של החודש הבא נמנה \u0003להבא\u0004 עם החודש האחר, ומותר בו.","וכן האומר \u0003\"שנה זו\" —\u0004 \u0003אסור בכל השנה, וראש השנה\u0004 של השנה הבאה נחשב \u0003לעתיד לבא\u0004 ולא בשנה זו. \u0003\"שבוע\u0004 (שבע שנים) \u0003זה\" —\u0004 \u0003אסור בכל השבוע, ו\u0004אם נדר בשנת השביעית (השמיטה) עצמה אסור גם ב\u0003שביעית שעברה,\u0004 כלומר, אף באותה שנה עצמה.","כל זה כשאמר \"יום זה\" \"שבוע זה\", \u0003ואם אמר\u0004 שהוא אסור \u0003\"יום אחד\" \"שבת אחת\" \"חדש אחד\" \"שנה אחת\" \"שבוע אחד\" —\u0004 \u0003אסור מיום ליום,\u0004 כלומר, אם נדר בלשון \"יום אחד\" אסור עד לאחר עשרים וארבע שעות. וכן \"שבת אחת\" אסור במשך שבוע שלם וכו'.","האומר שהוא אסור בדבר \u0003\"עד הפסח\" —\u0004 \u0003אסור עד שיגיע\u0004 חג הפסח, אמר \u0003\"עד שיהא\u0004 הפסח \u0003\"\u0004— \u0003אסור עד שיצא\u0004 חג הפסח. אם אמר \u0003\"עד לפני הפסח\", ר' מאיר אומר: אסור עד שיגיע\u0004 (יתחיל) חג הפסח, \u0003ר' יוסי אומר: אסור עד שיצא\u0004 (יגמר).","שנינו במשנה: האומר \u0003\"קונם יין שאני טועם\u0004 היום\" — אינו אסור אלא עד שתחשך. \u0003אמר ר' ירמיה: לכשתחשך\u0004 אינו מותר מיד, אלא \u0003צריך שאלה לחכם\u0004 שיתיר לו את נדרו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? הלא כבר עבר זמן הנדר! \u0003אמר רב יוסף: גזירה\u0004 גזרו על זה שאמר \u0003\"היום\" משום\u0004 זה שאומר \u0003\"יום אחד\",\u0004 שהוא אסור מעת לעת. שאם יותר לו נדרו מיד לכשתחשך, שמא ידור הוא או אחר ב\"יום אחד\", ויחשוב שגם במקרה זה הוא מותר עם חשיכה, ולכן הצריכוהו לבוא לחכם והחכם יברר באיזו לשון השתמש."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ליגזור\u0004 \u0005[שיגזור]\u0006 גם \u0003ב\u0004אומר \u0003\"יום אחד\" משום \"היום\",\u0004 ויהיה אסור גם ביום הבא עד שתחשך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003\"היום\" ב\"יום אחד\" מיחלף\u0004 \u0005[מתחלף]\u0006 בלשון בני אדם ולכן יש מצוה לגזור, אבל \u0003\"יום אחד\" ב\"היום\" לא מיחלף\u0004 \u0005[מתחלף]\u0006, שהכל יודעים ש\"יום אחד\" הוא מעת לעת.","\u0003אמר רבינא, אמר לי מרימר: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבוך משמיה\u0004 \u0005[אביך משמו]\u0006 של \u0003רב [יוסף]\u0004 : \u0003כמאן אזלא שמעתיה\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת שמועתו,\u0006 הלכתו\u0005]\u0006 זו של \u0003רב ירמיה בר אבא\u0004 שצריך שאלה לחכם כשתחשך — \u0003כ\u0004שיטת \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: כל הנודר —\u0004 \u0003כאילו בנה במה, והמקיימו —\u0004 \u0003כאילו מקטיר עליה.\u0004 ומשום כך, אף כשמקיים את הנדר, מוטב לו שיישאל לחכם ויעקור את הנדר מעיקרו, ויהא כאילו לא נדר.","שנינו במשנה שהאומר \u0003\"\u0004קונם יין שאני שותה \u0003שבת זו\", אסור בכל השבת כולה\u0004 וגם ביום השבת עצמו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי ל\u0003יומי דשבתא קאמר\u0004 \u0005[\u0006ל\u0005ימי השבוע אמר]\u0006 ונתכוון לאסור עצמו רק בימי השבוע ולא ביום השבת, על כן \u0003קא משמע\u0004 \u0003לן\u0004 \u0005[השמיע לנו]\u0006 שכאשר אמר \"שבת זו\" היתה כוונתו אף לשבת עצמה.","עוד שנינו במשנה שאם אמר \u0003\"חדש זה\" —\u0004 \u0003אסור בכל החדש וראש חדש\u0004 שאחריו שייך \u0003להבא\u0004 ואיננו אסור בו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003כי איצטריכא\u0004 \u0005[כאשר הוצרכה]\u0006 הלכה זו להיאמר הרי זה \u0003ל\u0004מקרה של \u0003חדש חסר,\u0004 שיש לפניו שני ימי ראש חודש, והוא נדר ביום הראשון של ראש החודש,","\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ראש חדש לשעבר הוי\u0004 \u0005[הוא],\u0006 שהרי יום ראשון של ראש חודש שייך למנין ימי החודש הקודם, \u0003ולא ליתסר\u0004 \u0005[ייאסר]\u0006 בו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003קרו אינשי ריש ירחא\u0004 \u0005[קוראים\u0006 לו \u0005אנשים ראש חודש]\u0006 על שם החודש הבא, ולכן יום זה שייך כבר לחודש הבא ונכלל אף הוא בלשון הנדר.","וכן שנינו לגבי האומר \u0003\"שנה זו\" —\u0004 \u0003אסור בכל השנה כולה\u0004 וראש השנה שייך לשנה הבאה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003אמר \"קונם יין שאני טועם יום\" מאי דיניה\u0004 \u0005[מה דינו]?\u0006 האם דינו כאילו אמר \u0003\"היום\"\u0004 ואסור עד שיחשיך היום, \u0003או\u0004 כמו שאמר \u0003\"יום אחד\"\u0004 ונאסר יממה שלימה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה \u0003ממתניתין\u0004 \u0005[ממשנתנו]\u0006 שנאמר בה \u0003\"קונם יין שאני טועם היום\" —\u0004 \u0003אין אסור אלא עד שתחשך.\u0004 ונדייק מכאן: דווקא אם אמר \"היום\" אבל \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר \u0003\"יום\" —\u0004 \u0003כ\"יום אחד\" דמי\u0004 \u0005[נחשב].\u0006","ודוחים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003אמר \"יום אחד\" —\u0004 \u0003אסור מיום ליום.\u0004 ומכאן אפשר לדייק: דווקא אם אמר \"יום אחד\" אבל \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר רק \u0003\"יום\" —\u0004 \u0003כ\u0004אילו אמר \u0003\"היום\" דמי\u0004 \u0005[נחשב].\u0006 \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין\u0006 אפשרות \u0005ללמוד ממנה]\u0006 בדרך דיוק, שאפשר לדייק לשני הצדדים.","\u0003אמר רב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, ששנינו: אמר \u0003\"קונם יין שאני טועם השנה\",\u0004 אם \u0003נתעברה השנה —\u0004 \u0003אסור בה ובעיבורה,\u0004 בחודש העיבור הנוסף לה. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006"],["\u0003אילימא כדקתני\u0004 \u0005[אם תאמר\u0006 בדיוק \u0005כמו ששנה]\u0006 — \u0003למה לי למימרא\u0004 \u0005[לומר]\u0006 דבר זה? הרי ברור ש\"השנה\" היא כל אותה שנה, כמה שתהיה. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שלא אמר \"השנה\", אלא ש\u0003אמר \"שנה\",\u0004 והשמיענו בברייתא כי נאסר כל אותה שנה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 יוצא ש\u0003\"שנה\" כ\"השנה\" דמי\u0004 \u0005[נחשב]\u0006, \u0003ו\u0004אם כן \u0003\"יום\" נמי\u0004 \u0005[גם כן]\u0006 \u0003כ\"היום\" דיניה\u0004 \u0005[דינו]\u0006.","ודוחים: \u0003לא, לעולם\u0004 תפרש את הברייתא כלשונה ש\u0003אמר \"השנה\", ו\u0004החידוש שבדבר — \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הלך אחר רוב השנים, ולא אית בהו\u0004 \u0005[ואין בהן]\u0006 \u0003עיבור,\u0004 ואף הוא נדר רק לשנה בת שנים עשר חודש, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שאמר \"השנה\" — נוהג איסור כפי שיהא אורכה של אותה השנה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 : \u0003אמר \"יין שאני טועם יובל\" מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006, האם \u0003שנת חמשים\u0004 עצמה נחשבת \u0003כלפני חמשים או כלאחר חמשים?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתניא פלוגתא\u0004 \u0005[ששנינו\u0006 בברייתא \u0005מחלוקת]\u0006 של \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 : נאמר \u0003\"וקדשתם את שנת החמשים שנה\"\u0004 (ויקרא כה, י), לומר: \u0003שנת החמשים אתה מונה,\u0004 קורא לשנת היובל, \u0003ואי\u0004 (ואין) \u0003אתה מונה\u0004 קורא לה גם \u0003שנת חמשים ו\u0004גם שנה \u0003אחת\u0004 (ראשונה) למנין היובל הבא. \u0003מכאן אמרו: יובל\u0004 עצמו \u0003אינו עולה\u0004 (נחשב) \u0003למנין\u0004 שנות \u0003שבוע\u0004 (שמיטה), אלא שנת היובל נחשבת לעצמה, והשנה שלאחר היובל נמנית כשנה ראשונה של השמיטה הבאה. \u0003ר' יהודה אומר: יובל עולה למנין שבוע,\u0004 ושנת היובל נחשבת שנה ראשונה בשמיטה הבאה.","\u0003אמרו לו\u0004 חכמים \u0003לר' יהודה:\u0004 \u0003הרי הוא אומר \"שש שנים תזרע שדך\"\u0004 (ויקרא כה, ג) \u0003ו\u0004לפי שיטתך \u0003אין כאן אלא חמש\u0004 שנים במחזור השמיטה הראשון, שהרי השנה הראשונה היא שנת היובל, האסורה גם כן בעבודת האדמה!","\u0003אמר להם\u0004 ר' יהודה: \u0003לדבריכם, הרי הוא אומר \"ועשת את התבואה לשלש השנים\"\u0004 (ויקרא כה, כא), שלפני שנת השמיטה תתן הארץ יבול מרובה שיספיק לשנה זו, לשנת השמיטה, ולחלק מן השנה שלאחריה עד שאפשר יהא לאכול מתבואתה. אולם אם שנת היובל נמנית לעצמה נמצא שהיא השנה שלאחר השמיטה, ויש איפוא שנה נוספת שאין זורעים בה, ואם כן \u0003הרי כאן ארבע\u0004 שנים הצריכות לסיפוק מזון!","\u0003אלא\u0004 מה אתם מפרשים — \u0003איכא לאוקמה\u0004 \u0005[אפשר להעמיד\u0006 את הפסוק\u0005]\u0006 \u0003בשאר שני שבוע,\u0004 בשנות שמיטה אחרות, ולא בשמיטה הסמוכה ליובל, אם כן \u0003דילי\u0004 \u0005[שלי]\u0006 את הפסוק הקשה עלי בענין \"שש שנים תזרע\" \u0003נמי איכא לאוקמה\u0004 \u0005[גם כן אפשר להעמיד]\u0006 \u0003בשאר שני שבוע\u0004 בשמיטות אחרות שאינן סמוכות ליובל. ולענייננו, אם שנת היובל נמנית עם מחזור השמיטה הבא — הנודר באמצע שנות היובל לא כלל בתוכו את שנת היובל הבאה, ואם שנת היובל אינה נמנית עם מחזור השמיטה הבא, הרי הנודר ביובל נאסר אף בשנת היובל הקרובה.","שנינו במשנה כי הנודר \u0003\"עד הפסח\" אסור\u0004 עד שיגיע הפסח, ונחלקו כשאומר \"עד לפני הפסח\" אם אסור עד שיגיע הפסח, או אסור עד שייצא. ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003ר' מאיר\u0004 האוסר רק עד שיגיע הפסח \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003לא מעייל איניש נפשיה\u0004 \u0005[אין אדם מכניס עצמו]\u0006"],["\u0003לספיקא\u0004 \u0005[לספק],\u0006 כלומר, בכל מקום שעשוי להיות ספק במשמעות הדברים שמשמיע אדם — אין אדם מתכוון להכניס את עצמו לתחום המסופק, ולא אסר את עצמו בו. \u0003ו\u0004אילו \u0003ר' יוסי סבר: מעייל איניש נפשיה לספיקא\u0004 \u0005[מכניס אדם עצמו לספק].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003מי שיש לו שתי כיתי\u0004 (קבוצות) \u0003בנות\u0004 שנולדו לו \u0003משתי נשים\u0004 שנשא בזמנים שונים, ויש לו מאשה אחת שתי בנות ומן האשה האחרת שתי בנות יותר קטנות, \u0003ואמר: קדשתי את בתי הגדולה\u0004 לאיש פלוני, \u0003ואיני יודע אם\u0004 היתה כוונתי ל\u0003גדולה שבגדולות\u0004 שבכת ראשונה, \u0003אם גדולה שבקטנות\u0004 שבכת השניה, \u0003ואם\u0004 היתה כוונתי ל\u0003קטנה שבגדולות שהיא גדולה מן הגדולה שבקטנות —\u0004 \u0003כולן אסורות\u0004 מספק, פרט לקטנה ביותר, שהרי לא בירר את מי מהן קידש. אלו \u0003דברי ר' מאיר. חוץ מן הקטנה שבקטנות.\u0004","\u0003ר' יוסי אומר: כולן מותרות, חוץ מן הגדולה שבגדולות.\u0004 הרי שלדעת ר' מאיר הלשון הבלתי ברורה \"בתי הגדולה\" כוללת בתוכה גם את הספיקות, ואילו לר' יוסי רק מה שהוא ודאי נכלל בכך!","\u0003אמר ר' חנינא בר אבדימי אמר רב: מוחלפת השיטה,\u0004 כלומר, צריך להחליף את דעות בעלי השיטות במשנתנו, כדי להתאימן לדעות שבמסכת קדושין. \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן\u0006 \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003זה הכלל: כל\u0004 מאורע \u0003שזמנו קבוע\u0004 ונדר \u0003ואמר \"עד לפני\"\u0004 אותו מאורע — \u0003ר' מאיר אומר:\u0004 נאסר \u0003עד שיצא, ור' יוסי אומר: עד שיגיע.\u0004 והרי זו ראיה נוספת שיש להחליף את השיטות במשנתנו.","האוסר דבר על עצמו \u0003\"עד הקציר\u0004 (של התבואה)\u0003\",\u0004 או \u0003\"עד הבציר\"\u0004 (של הענבים), או \u0003\"עד המסיק\"\u0004 (של זיתים) — \u0003אינו אסור אלא עד שיגיע\u0004 זמן זה. \u0003זה הכלל: כל\u0004 מאורע \u0003שזמנו קבוע ואמר\u0004 \u0003\"עד שיגיע\"\u0004 מאורע זה — \u0003אסור עד שיגיע. אמר\u0004 על אותו מאורע \u0003\"עד שיהא\" —\u0004 \u0003אסור עד שיצא. וכל שאין זמנו קבוע,\u0004 שאין לו תאריכים קבועים, \u0003בין אמר \"עד שיהא\" בין אמר \"עד שיגיע\" —\u0004 \u0003אינו אסור אלא עד שיגיע.\u0004","אמר \u0003\"עד הקיץ\",\u0004 או \u0003\"עד שיהא הקיץ\"\u0004 — הרי קיץ זה הוא זמן קטיף פירות הקיץ, ובפרט התאנים, ונאסר \u0003עד שיתחילו העם להכניס\u0004 את התאנים \u0003בכלכלות\u0004 (בסלים) אל הבית. אם אמר \u0003\"עד שיעבור הקיץ\" —\u0004 אסור \u0003עד שיקפילו המקצועות,\u0004 שיחזירו למקומם את הסכינים שקוצצים בהם את התאנים.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 : \u0003\"כלכלה\"\u0004 זו \u0003שאמרו\u0004 במשנה — \u0003כלכלה של תאנים\u0004 היא, \u0003ולא כלכלה של ענבים\u0004 שנבצרות מאוחר יותר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003הנודר מפירות הקיץ —\u0004 \u0003אין אסור אלא בתאנים,\u0004 שהן נקראות \"קיץ\". \u0003רבן שמעון בן גמליאל אומר: ענבים בכלל תאנים,\u0004 כלומר, בכלל \"פירות הקיץ\".","שואלים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006? ומשיבים, \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 : כיון ש\u0003תאנים מיקצצן בידא\u0004 \u0005[נקצצות ביד]\u0006, ואילו \u0003ענבים לא מיקצצן בידא\u0004 \u0005[אינן נקצצות ביד]\u0006 אלא במזמרה, לכן רק התאנים נקראות \"פירות הקיץ\". \u0003רבן שמעון בן גמליאל סבר: ענבים נמי\u0004 \u0005[גם כן]\u0006, \u0003כי מירדדן\u0004 \u0005[כאשר\u0006 הם \u0005בשלים\u0006 יפה\u0005] —\u0006 \u0003מיקצצן בידא\u0004 \u0005[\u0006הם \u0005נקצצים ביד]\u0006 ולכן אפשר לקרוא גם להם \"פירות הקיץ\".","שנינו במשנה שאם אמר \u0003\"עד שיעבור הקיץ\",\u0004 כוונתו \u0003עד שיכפלו המקצועות. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 : \u0003עד שיכפילו רוב המקצועות,\u0004 ואינו צריך לחשוש ליחידים שעדיין לא עשו זאת."]]};
